            }
        } elseif ($request->request_type == 'check_room_availability') {
            $chko_date = ($request->checkinDate == $request->checkoutDate) ? date("Y-m-d", strtotime($request->checkoutDate)) : date("Y-m-d", strtotime($request->checkoutDate  . '-1 days'));
            $BlockedHotel = BlockedHotel::where('hotel_id', $request->hotelId)
                ->whereBetween('block_date', [date("Y-m-d", strtotime($request->checkinDate)), $chko_date])
                ->pluck('rooms')->toArray();
            $BlockedRooms = array();
            if (!empty($BlockedHotel)) {
                $BlockedRoomsStr = implode(",", $BlockedHotel);
                $BlockedRooms = explode(",", $BlockedRoomsStr);
                $BlockedRooms = array_unique($BlockedRooms);
            }
            // if (!empty($BlockedHotel)) {
            //     $responce['status'] = 0;
            //     $responce['message'] = 'Rooms not available';
            //     $responce['message1'] = $BlockedHotel;
            // } else {
            $difference = strtotime($request->checkoutDate) - strtotime($request->checkinDate);
            $days = ($request->checkinDate == $request->checkoutDate) ? 1 : round($difference / (60 * 60 * 24));

            $CustomRooms = HotelRoom::where(['hotel_id' => $request->hotelId, 'status' => 'publish'])->get()->toArray();
            foreach ($CustomRooms as $key => $room) {
                if (!empty($BlockedRooms) && in_array($room['id'], $BlockedRooms)) {
                    unset($CustomRooms[$key]);
                    continue;
                }
                $room_quantity = array();
                for ($i = 0; $i < $days; $i++) {
                    $checkDate = date("Y-m-d", strtotime($request->checkinDate . ' + ' . $i . ' days'));
                    $MasterInventory = MasterInventory::where(["date" => $checkDate, 'room_id' => $room['id']])->first();
                    if ($request->bookFrom == 'live') {
                        $total_available = !empty($MasterInventory) ? $MasterInventory->total_available : 0;
                        if ($total_available < 1) {
                            unset($CustomRooms[$key]);
                            continue 2;
                        } else {
                            array_push($room_quantity, $total_available);
                        }
                    } else {
                        $total_available = !empty($MasterInventory) ? $MasterInventory->total_blocked : 0;
                        if ($total_available < 1) {
                            unset($CustomRooms[$key]);
                            continue 2;
                        } else {
                            array_push($room_quantity, $total_available);
                        }
                    }
                }
                $CustomRooms[$key]['quantity'] = $room['quantity'] = min($room_quantity);
                $customer_price = 0;
                if ($request->checkinDate != '') {
                    $CustomRooms[$key]['actual_price'] = $CustomRooms[$key]['price'] * $days;
                    $RoomPricing = HotelRoomPricing::where('room_id', $room['id'])
                        ->whereBetween('start_date', [date("Y-m-d", strtotime($request->checkinDate)), date("Y-m-d", strtotime($request->checkoutDate))])
                        ->get()->toArray();
                    $Pricing_data = array();
                    if (!empty($RoomPricing)) {
                        foreach ($RoomPricing as $pricing) {
                            $Pricing_data[$pricing['start_date']] = $pricing;
                        }
                    }
                    $pricing_array = array();
                    for ($i = 0; $i < $days; $i++) {
                        $date = date("Y-m-d", strtotime($request->checkinDate . ' + ' . $i . ' days'));
                        if (!empty($Pricing_data) && array_key_exists($date, $Pricing_data)) {
                            $offer_value = $Pricing_data[$date]['offer_percentage']; //($CustomRooms[$key]['price'] * ($Pricing_data[$date]['offer_percentage'] / 100));
                            $calculated_price = 0;
                            if ($Pricing_data[$date]['offer_type'] == 'plus') {
                                $calculated_price = floatval($CustomRooms[$key]['price'] + $offer_value);
                            } else {
                                $calculated_price = floatval($CustomRooms[$key]['price'] - $offer_value);
                            }
                            $customer_price += $calculated_price;
                            $pricing_array[$date] = array('actual_price' => $CustomRooms[$key]['price'], 'price' => $calculated_price, 'offer_value' => $offer_value);
                        } else {
                            $customer_price += $CustomRooms[$key]['price'];
                            $pricing_array[$date] = array('actual_price' => $CustomRooms[$key]['price'], 'price' => $CustomRooms[$key]['price'], 'offer_value' => 0);
                        }
                    }
                }
                $CustomRooms[$key]['price'] = $customer_price;
                $CustomRooms[$key]['pricing_details'] = array_merge($pricing_array);
                $CustomRooms[$key]['days'] = $days;

                $bed_option = array();
                $max_bed = $room['adults'] + $room['children'] + $room['extra_bed_allowed'];
                $minAdult = $room['adults'];
                $maxLoop = $inLoop = (($max_bed - $minAdult) < $minAdult) ? $minAdult : $max_bed - $minAdult;
                $count = 1;
                while ($count < $room['adults']) {
                    $bed_option[] = array('adult' => $count, 'child' => 0, 'extra' => 0, 'price' => $customer_price, 'sts' => 0);
                    $count++;
                }

                for ($i = 0; $i <= $maxLoop; $i++) {
                    for ($j = 0; $j <= $inLoop; $j++) {
                        $exbed = 0;
                        if ($j == 0) {
                            $exbed = ($minAdult > $room['adults']) ? $minAdult - $room['adults'] : 0;
                        } else {
                            if (($minAdult > $room['adults']) && ($j > $room['children'])) {
                                $exbed = ($minAdult + $j) - ($room['adults'] + $room['children']);
                            } elseif ($j > $room['children']) {
                                $exbed = $j - $room['children'];
                            } elseif ($minAdult > $room['adults']) {
                                $exbed = $minAdult - $room['adults'];
                            }
                        }
                        if ((($minAdult + $j) <= $max_bed) && $minAdult <= ($room['adults'] + $room['extra_bed_allowed'])) {
                            $listPrice = $customer_price + ($exbed * $room['extra_bed_price'] * $days);
                            $status = ($j > 0 && $exbed > 0) ? 1 : 0;
                            $bed_option[] = array('adult' => $minAdult, 'child' => $j, 'extra' => $exbed, 'price' => $listPrice, 'sts' => $status);
                        }
                    }
                    $minAdult++;
                    $inLoop = $max_bed - $minAdult;
                }
                $CustomRooms[$key]['guestdata'] = $bed_option;
            }
            if (!empty($CustomRooms)) {
                $GSTData = GstDetail::pluck('value', 'name');
                $responce['gst_data'] = $GSTData;
                $MasterHotel = MasterHotel::find($request->hotelId);
                $responce['gstApplicable'] = $MasterHotel->gst_applicable;
                $responce['service_chagre'] = $MasterHotel->service_fee;
                $HotelRooms = array_merge($CustomRooms);
                $responce['status'] = 1;
                $responce['data'] = $HotelRooms;
            } else {
                $responce['status'] = 0;
                $responce['message'] = 'Rooms not available';
            }
            // }
