                $checkin = date("Y-m-d", strtotime($request->checkIn));
                $checkout = date("Y-m-d", strtotime($request->checkOut));
                if ($checkin == $checkout) {
                    $days = 1;
                } else {
                    $difference = strtotime($checkout) - strtotime($checkin);
                    $days = round($difference / (60 * 60 * 24));
                }
                if ($MasterHotel->gst_applicable == 1) {
                    $GSTData = GstDetail::pluck('value', 'name')->toArray();
                    $GstTable = GstTable::where(['vendor_id' => $MasterHotel->vender_id, 'service_type' => 'hotel'])
                        ->orderBy('min_amount', 'asc')
                        ->pluck('gst', 'min_amount')->toArray();
                    $GstDetails = array();
                    if (!empty($GstTable)) {
                        foreach ($GstTable as $k => $gst) {
                            $GstDetails[$k] = json_decode($gst, 1);
                        }
                    } else {
                        $GstDetails[0] = $GSTData;
                    }
                    $GstMin = array_keys($GstDetails);
                }
                $GstShowData = $tax_array = array();
                $total_gst = $gross_price = $SubTotal = $extra_price = 0;

                foreach ($room_details as $value) {
                    $extra_bed_price = $value['extra_bed'] * $value['extra_bed_price'];
                    $extra_price += $extra_bed_price;
                    for ($i = 0; $i < $days; $i++) {
                        $checkInDate = date("Y-m-d", strtotime($checkin . ' + ' . $i . ' days'));
                        $checkOutDate = date("Y-m-d", strtotime($checkin . ' + ' . ($i + 1) . ' days'));
                        if ($checkin == $checkout) {
                            $checkOutDate = $checkInDate;
                        }
                        $price = $Pricing_data[$value['id']][$checkInDate]['price'] + $extra_bed_price;
                        $SubTotal += $price;
                        if ($MasterHotel->gst_applicable == 1) {
                            $filter_res = array_filter($GstMin, function ($n) use ($price) {
                                return $n <= $price;
                            });
                            if (!empty($filter_res)) {
                                $tempr = $GstDetails[end($filter_res)];
                                if (!empty($tax_array)) {
                                    foreach ($tempr as $g_name => $g_val) {
                                        $tax_amt = $price * ($g_val / 100);
                                        $tax_array[$g_name] += $tax_amt;
                                    }
                                } else {
                                    foreach ($tempr as $g_name => $g_val) {
                                        $tax_amt = $price * ($g_val / 100);
                                        $tax_array[$g_name] = $tax_amt;
                                    }
                                }
                            }
                        }
                    }
                }
                foreach ($tax_array as $key => $val) {
                    $GstShowData[] = [
                        'gst_name' => $key,
                        'gst_percentage' => $tempr[$key],
                        'gst_value' => ceil($val)
                    ];
                    $total_gst += ceil($val);
                }
                $responce['status'] = 1;
                $responce['gst_data'] = $GstShowData;
                $responce['grossPrice'] = $responce['subTotalPrice'] = ceil($SubTotal);
                $responce['totalOrderPrice'] = ceil($SubTotal + $total_gst + $MasterHotel->service_fee);
                $responce['extra_price'] = $extra_price * $days;
            }
        } elseif ($request->request_type == 'change_master_inventory') {
