                                                ->whereRaw("(platform LIKE 'all' OR platform LIKE 'cleartrip')")
                                                ->get()->toArray();
                                    if (!empty($BlockedMmt)) {
                                        $closed = "Close";
                                    }
                                    $Xml = '<OTA_HotelAvailNotifRQ xmlns="http://www.opentravel.org/OTA/2003/05" Version="1.0" EchoToken="1234">
                                                <AvailStatusMessages HotelCode="'. $MasterHotel->ctp_hotel_id .'">
                                                    <AvailStatusMessage BookingLimit="'. $inventory->total_available .'">
                                                        <StatusApplicationControl Start="'. $inventory->date .'" End="'. $inventory->date .'" InvTypeCode="'. $HotelRoom->ctp_room_id .'" RatePlanCode="'. $InvRateplanData->rate_plan_code .'" />
                                                        <RestrictionStatus Status="'. $closed .'" />
                                                    </AvailStatusMessage>
                                                </AvailStatusMessages>
                                            </OTA_HotelAvailNotifRQ>';
                                    DB::insert("INSERT INTO `ctp_availability_logs`(`request_source`, `vendor_id`, `hotel_id`, `hotel_code`, `room_id`, `room_code`, `request_data`, `status`, `created_at`, `request_type`, `quantity`, `date`) VALUES ('delete_full_block_web', '". $MasterHotel->vender_id ."', '". $MasterHotel->id ."', '". $MasterHotel->ctp_hotel_id ."', '". $HotelRoom->id ."', '". $HotelRoom->ctp_room_id . "', '". $Xml ."', '0', '". date('Y-m-d H:i:s') ."', 'inventory', '". $inventory->total_available ."', '". $inventory->date ."')");
                                }
                            }
                        }
                    }
                }
                DB::table('blocked_hotels')->whereIn('id', $item_array)->delete();
                $responce['status'] = 1;
                $responce['message'] = 'Block data deleted successfully.';
            }
        } elseif ($request->request_type == 'get_initial_room_quantity') {
