                            ->where('OD.start_date', '<=', $check_date)
                            ->where('OD.end_date', '>', $check_date)
                            ->select('OM.*')
                            ->groupBy('OM.id')
                            ->get();
                    if (!empty($Orders->toArray())) {
                        $MisHotelData = array();
                        foreach ($Orders as $key => $value) {
                            $hotelId = $hotelName = $rooms = $start_date = $end_date = '';$night = $total_occ = 0;
