                                        $add_child = 0;
                                        if (isset($roomno['Age']) && is_array($roomno['Age'])) {
                                            $filter_res = array_filter($roomno['Age'], function($n) { return $n > 6; });
                                            if (!empty($filter_res)) { $add_child = count($filter_res); }
                                        } elseif (isset($roomno['Age'])) {
                                            $add_child = ($roomno['Age'] > 6) ? $roomno['Child'] : 0;
