                            if ($value->total_rooms > 1) {
                                foreach ($room_request as $roomno) {
                                    if ($roomno['Child'] > 0) {
                                        $add_child = 0;
                                        if (isset($roomno['Age']) && is_array($roomno['Age'])) {
                                            $filter_res = array_filter($roomno['Age'], function($n) { return $n > 6; });
                                            if (!empty($filter_res)) { $add_child = count($filter_res); }
                                        } elseif (isset($roomno['Age'])) {
                                            $add_child = ($roomno['Age'] > 6) ? $roomno['Child'] : 0;
                                        }
                                        if ($roomno['Child'] < $HotelRoom->children || $HotelRoom->children == 0) {
                                            $total_occ += $roomno['Adult'] + $add_child;
                                        } else {
                                            $total_occ += ($roomno['Adult'] + $roomno['Child'] + $add_child) - $HotelRoom->children;
                                        }
                                    } else {
                                        $total_occ += $roomno['Adult'];
                                    }
                                }
                            } else {
