        } elseif ($request->request_type == 'export_hotel_book_count_with_block') {
            if (!(parent::checkWritePrivilege(91))) {
                $responce['status'] = 0;
                $responce['message'] = 'You are not autherised to do this operation.';
            } else {
                $HotelList = MasterHotel::where('id', $request->hotelId)->pluck('name', 'id')->toArray();
                $start_date = date("Y-m-d", strtotime($request->check_date));
                if (!empty($HotelList)) {
                    $vender_id = (Auth::user()->role == 2) ? Auth::user()->id : Auth::user()->vendor_id;
                    $HotelId = 0;
                    $MisData = array();
                    $select = '';
                    $bookFrom = $request->book_from;
                    if ($bookFrom == 'online') {
                        $select = '(SUM(total_booked) + SUM(total_blocked) - SUM(total_mmt_booking)) AS totBook';
                    } elseif ($bookFrom == 'mmt') {
                        $select = '(SUM(total_mmt_booking) + SUM(total_blocked)) AS totBook';
                    } elseif ($bookFrom == 'all') {
                        $select = '(SUM(total_booked) + SUM(total_blocked)) AS totBook';
                    }
                    foreach ($HotelList as $key => $value) {
                        $HotelId = $key;
                        $MisData['name'] = $value;
                        $HotelRoom = HotelRoom::where(['hotel_id' => $key, 'status' => 'publish'])->orderBy('price', 'DESC')->get()->toArray();  // ->pluck('title', 'id')
                        if (!empty($HotelRoom)) {
                            $roomIds = array_column($HotelRoom, 'id');
                            $roomName = array_column($HotelRoom, 'title');
                            $roomQty = array_column($HotelRoom, 'quantity');
                            $MisData['rooms'] = array_combine($roomName, $roomQty);
                            $roomData = array();
                            foreach ($HotelRoom as $room) {
                                $BeforeTodayQry = MasterInventory::select('room_id', DB::raw($select))
                                            ->where('hotel_id', $key)
                                            ->where('room_id', $room['id'])
                                            ->where('date', '<', $start_date);
                                if ($vender_id == 3) {
                                    $BeforeTodayQry->where('date', '>', $this->ecoStartDate);
                                }
                                $BeforeToday = $BeforeTodayQry->first()->toArray();

                                // $BeforeToday = MasterInventory::select('room_id', DB::raw($select))
                                //             ->where('hotel_id', $key)
                                //             ->where('room_id', $room['id'])
                                //             ->where('date', '<', $start_date)
                                //             ->first()
                                //             ->toArray();
                                $MisData['before'][$room['id']] = 0;
                                if (!empty($BeforeToday['totBook'])) {
                                    $MisData['before'][$room['id']] = $BeforeToday['totBook'];
                                }

                                $AllBookedQry = MasterInventory::select('room_id', DB::raw($select))
                                        ->where('hotel_id', $key)
                                        ->where('room_id', $room['id']);
                                if ($vender_id == 3) {
                                    $AllBookedQry->where('date', '>', $this->ecoStartDate);
                                }
                                $AllBooked = $AllBookedQry->first()->toArray();

                                // $AllBooked = MasterInventory::select('room_id', DB::raw($select))
                                //             ->where('hotel_id', $key)
                                //             ->where('room_id', $room['id'])
                                //             ->first()
                                //             ->toArray();
                                $MisData['allBooked'][$room['id']] = 0;
                                if (!empty($AllBooked['totBook'])) {
                                    $MisData['allBooked'][$room['id']] = $AllBooked['totBook'];
                                }

                                $AllInitialQry = MasterInventory::select('room_id', DB::raw('SUM(initial_quantity) AS totBook'))
                                        ->where('hotel_id', $key)
                                        ->where('room_id', $room['id']);
                                if ($vender_id == 3) {
                                    $AllInitialQry->where('date', '>', $this->ecoStartDate);
                                }
                                $AllInitial = $AllInitialQry->first()->toArray();

                                // $AllInitial = MasterInventory::select('room_id', DB::raw('SUM(initial_quantity) AS totBook'))
                                //             ->where('hotel_id', $key)
                                //             ->where('room_id', $room['id'])
                                //             ->first()
                                //             ->toArray();
                                $MisData['allInitial'][$room['id']] = 0;
                                if (!empty($AllInitial['totBook'])) {
                                    $MisData['allInitial'][$room['id']] = $AllInitial['totBook'];
                                }

                                $MasterInventoryQry = MasterInventory::where('hotel_id', $key)
                                            ->where('room_id', $room['id'])
                                            ->where('date', '>=', $start_date);
                                if ($vender_id == 3) {
                                    $MasterInventoryQry->where('date', '>', $this->ecoStartDate);
                                }
                                $MasterInventory = $MasterInventoryQry->orderBy('date', 'ASC')->get();

                                // $MasterInventory = MasterInventory::where('hotel_id', $key)
                                //                 ->where('room_id', $room['id'])
                                //                 ->where('date', '>=', $start_date)
                                //                 ->orderBy('date', 'ASC')
                                //                 ->get();

                                foreach ($MasterInventory as $booked) {
                                    $total_booked = 0;
                                    if ($bookFrom == 'online') {
                                        $total_booked = $booked->total_booked + $booked->total_blocked - $booked->total_mmt_booking;
                                    } elseif ($bookFrom == 'mmt') {
                                        $total_booked = $booked->total_mmt_booking + $booked->total_blocked;
                                    } elseif ($bookFrom == 'all') {
                                        $total_booked = $booked->total_booked + $booked->total_blocked;
                                    }
                                    $roomData[$booked->date][$room['id']] = $total_booked;
                                }
                            }
                        }
                        $MisData['data'] = $roomData;
                    }
                    $spreadsheet = new Spreadsheet();
                    $sheet = $spreadsheet->getActiveSheet();
                    $total_column = count($MisData['rooms']) + 2;

                    $sheet->mergeCellsByColumnAndRow(1, 1, $total_column, 1);
                    $sheet->setCellValueByColumnAndRow(1,1,'Booking status of '. $MisData['name'] .' as on ('. date("d-m-Y h:i a") .')');
                    $sheet->mergeCells('A2:A3');
                    $sheet->setCellValueByColumnAndRow(1,2,'Tent Capacity');
                    $sheet->setCellValueByColumnAndRow(1,4,'Up to '. date("d.m.Y", strtotime($start_date .' -1 days')));
                    $j = 1;
                    $total = 0;
                    foreach($MisData['rooms'] as $keys => $x_value) {
                        $sheet->setCellValueByColumnAndRow(++$j,2,$keys);
                        $sheet->setCellValueByColumnAndRow($j,3,$x_value);
                        $total += $x_value;
                    }
                    $sheet->setCellValueByColumnAndRow($total_column,2,'Total');
                    $sheet->setCellValueByColumnAndRow($total_column,3,$total);
                    $j = 1;
                    $total = 0;
                    foreach($MisData['before'] as $keys => $x_value) {
                        $sheet->setCellValueByColumnAndRow(++$j,4,$x_value);
                        $total += $x_value;
                    }
                    $sheet->setCellValueByColumnAndRow($total_column,4,$total);

                    $i = 5;
                    foreach($MisData['data'] as $dt_key => $sheets_data){
                        // if (array_sum(array_values($sheets_data)) > 0) {
                            $j = 1;
                            $total = 0;
                            $sheet->setCellValueByColumnAndRow($j,$i,date("d.m.Y", strtotime($dt_key)));
                            foreach ($sheets_data as $value) {
                                $sheet->setCellValueByColumnAndRow(++$j,$i,$value);
                                $total += $value;
                            }
                            $sheet->setCellValueByColumnAndRow($total_column,$i,$total);
                            $i++;
                        // }
                    }
                    $sheet->setCellValueByColumnAndRow(1,$i,'Tent Night Sold');
                    $j = 1;
                    $sold_total = 0;
                    foreach($MisData['allBooked'] as $keys => $x_value) {
                        $sheet->setCellValueByColumnAndRow(++$j,$i,$x_value);
                        $sold_total += $x_value;
                    }
                    $sheet->setCellValueByColumnAndRow($total_column,$i,$sold_total);
                    $i++;
                    $sheet->setCellValueByColumnAndRow(1,$i,'Tent Night Available');
                    $j = 1;
                    $avail_total = 0;
                    foreach($MisData['allInitial'] as $keys => $x_value) {
                    //     $sheet->setCellValueByColumnAndRow(++$j,$i,$x_value);
                        $avail_total += $x_value;
                    }
                    // $sheet->setCellValueByColumnAndRow($total_column,$i,$avail_total);
                    // $i++;
                    $occ_percent = ($sold_total != 0 && $avail_total != 0) ? round(($sold_total / $avail_total) * 100, 2) : 0;
                    $sheet->mergeCellsByColumnAndRow(1, $i, $total_column, $i);
                    $sheet->setCellValueByColumnAndRow(1,$i,'% of Occupancy '. $occ_percent);

                    $file_name = 'documents/Book_count_with_block_report_'. $MisData['name'] .'_'. date("d-m-Y h-i-s") .'.xlsx';
                    $xsl_name = public_path($file_name);

                    $writer = new Xlsx($spreadsheet);
                    $writer->save($xsl_name);

                    $responce['status'] = 1;
                    $responce['file_path'] = $this->site . $file_name;
                } else {
                    $responce['status'] = 0;
                    $responce['message'] = 'Unable to export report. Please try again.';
                }
                // // $file = 'documents/Order_' . time() . '.pdf';
