                    $MasterHotelQuery->where('vender_id', $vender_id);
                    if ((Auth::user()->role == 3)) {
                        $SubuserAccess = SubuserAccess::where(['user_id' => Auth::user()->id, 'service' => 'hotel'])->pluck('service_id', 'id')->toArray();
                        if (!empty($SubuserAccess)) {
                            $MasterHotelQuery->whereIn('id', array_values($SubuserAccess));
                        }
                    }
                }
                $MasterHotel = $MasterHotelQuery->orderBy('id', 'ASC')->pluck('name', 'id')->toArray();
                $hotelList = array();
                $start_date = date("Y-m-d", strtotime($request->startDate));
                $end_date = date("Y-m-d", strtotime($request->endDate));
                $date_type = 'OD.'. $request->report_type;
                $gst_percent = $request->gst_percent;
                if ($request->hotel_id != 0) {
                    $hotelList[$request->hotel_id] = $MasterHotel[$request->hotel_id];
                } else {
                    $hotelList = $MasterHotel;
                }
                $MisData = array();
                $GSTDataQuery = DB::table('order_details AS OD')
                            ->join('order_masters AS OM', 'OD.order_master_id', '=', 'OM.id')
                            ->select('OM.invoice_id', 'OM.invoice_serial', 'OM.gst_regd_no', 'OD.service_name', 'OD.service_item_name', 'OD.start_date', 'OD.end_date', 'OM.created_at', DB::raw('(OD.unit_total_price - OD.coupon_amount) AS sub_toal') , 'OD.tax_percentage', 'OD.tax_amount', 'OD.total_room_price')
                            ->where(['OD.service_type' => 'hotel',  'OM.status' => 'completed', 'OM.payment_status' => 'success'])
                            ->whereIn('OD.service_name_id', array_keys($hotelList))
                            ->whereBetween($date_type, [$start_date .' 00:00:00', $end_date .' 23:59:59']);
                if ($vender_id != 0) {
                    $GSTDataQuery->where('OM.vendor_id', $vender_id);
                }
                if ($gst_percent != '0') {
                    $GSTDataQuery->where('OD.tax_percentage', $gst_percent);
                }
                $MisData = $GSTDataQuery->get()->toArray();

                $spreadsheet = new Spreadsheet();
                $sheet = $spreadsheet->getActiveSheet();

                $sheet->setCellValueByColumnAndRow(1,1,'Booking Id');
                $sheet->setCellValueByColumnAndRow(2,1,'Invoice Slno');
                $sheet->setCellValueByColumnAndRow(3,1,'Book Date');
                $sheet->setCellValueByColumnAndRow(4,1,'Customer GST No');
                $sheet->setCellValueByColumnAndRow(5,1,'Hotel Name');
                $sheet->setCellValueByColumnAndRow(6,1,'Room Type');
                $sheet->setCellValueByColumnAndRow(7,1,'Check In');
                $sheet->setCellValueByColumnAndRow(8,1,'Check Out');
                $sheet->setCellValueByColumnAndRow(9,1,'Sub Total Amount');
                $sheet->setCellValueByColumnAndRow(10,1,'GST Percent');
                $sheet->setCellValueByColumnAndRow(11,1,'GST Amount');
                $sheet->setCellValueByColumnAndRow(12,1,'Total Amount');

                $i = 2;
                $total = 0;
                $total_sub = $total_gst = $grand_total = 0;
                foreach($MisData as $val) {
                    $sheet->setCellValueByColumnAndRow(1,$i,$val->invoice_id);
                    $sheet->setCellValueByColumnAndRow(2,$i,$val->invoice_serial);
                    $sheet->setCellValueByColumnAndRow(3,$i,date("d-m-Y h:i a", strtotime($val->created_at)));
                    $sheet->setCellValueByColumnAndRow(4,$i,$val->gst_regd_no);
                    $sheet->setCellValueByColumnAndRow(5,$i,$val->service_name);
                    $sheet->setCellValueByColumnAndRow(6,$i,$val->service_item_name);
                    $sheet->setCellValueByColumnAndRow(7,$i,date("d-m-Y", strtotime($val->start_date)));
                    $sheet->setCellValueByColumnAndRow(8,$i,date("d-m-Y", strtotime($val->end_date)));
                    $sheet->setCellValueByColumnAndRow(9,$i,$val->sub_toal);
                    $sheet->setCellValueByColumnAndRow(10,$i,(int)$val->tax_percentage);
                    $sheet->setCellValueByColumnAndRow(11,$i,$val->tax_amount);
                    $sheet->setCellValueByColumnAndRow(12,$i,$val->total_room_price);
                    $i++;
                    $total_sub += $val->sub_toal;
                    $total_gst += $val->tax_amount;
                    $grand_total += $val->total_room_price;
                }
                $sheet->mergeCellsByColumnAndRow(1, $i, 8, $i);
                $sheet->setCellValueByColumnAndRow(1,$i,'TOTAL');
                $sheet->setCellValueByColumnAndRow(9,$i,$total_sub);
                $sheet->setCellValueByColumnAndRow(11,$i,$total_gst);
                $sheet->setCellValueByColumnAndRow(12,$i,$grand_total);

                $file_name = 'documents/Hotel_GST_report_'. date("d-m-Y", strtotime($start_date)) .' - '. date("d-m-Y", strtotime($end_date)) .'.xlsx';
                $xsl_name = public_path($file_name);

                $writer = new Xlsx($spreadsheet);
                $writer->save($xsl_name);

                $responce['status'] = 1;
                $responce['file_path'] = $this->site . $file_name;
            }
        } elseif ($request->request_type == 'export_hotel_estimates') {
            $Data = DB::select($request->exportQuery);
            $csv = "documents/hotel_estimates_" . date('d-m-y h-i-a') . ".csv";
            $csvname = public_path($csv);

            $headerArr = array('Estimate ID', 'Hotel Name', 'Room Type', 'Check In', 'Check Out', 'Customer Name', 'Customer Phone', 'Customer Email', 'Total Rooms', 'Adult', 'Child', 'No of Nights', 'Total room Nights', 'Gross Price', 'Discount', 'Sub Total Price', 'CGST', 'SGST', 'Total Price', 'Estimate Date');

            $fp = fopen($csvname, 'w');
            fputcsv($fp, $headerArr);
            if (!empty($Data)) {
                foreach ($Data as $value) {
                    $room_details = json_decode($value->room_details, 1);
                    $rom_html = '';
                    foreach ($room_details as $room) {
                        $rom_html.= $room['quantity'] .' '. $room['room_name'] .',';
                    }
                    $rooms = rtrim($rom_html, ',');
                    $difference = strtotime($value->end_date) - strtotime($value->start_date);
                    $days = round($difference / (60 * 60 * 24));
                    $night = ($days == 0) ? 1 : $days;

                    $data['invoice_id'] = $value->invoice_id;
                    $data['service_name'] = $value->service_name;
                    $data['room_type'] = $rooms;
                    $data['start_date'] = $value->start_date;
                    $data['end_date'] = $value->end_date;
                    $data['customer_name'] = $value->customer_name;
                    $data['customer_phone'] = $value->customer_phone;
                    $data['customer_email'] = $value->customer_email;
                    $data['total_rooms'] = $value->total_rooms;
                    $data['total_adults'] = $value->total_adults;
                    $data['total_child'] = $value->total_child;
                    $data['night'] = $night;
                    $data['block_reason'] = $value->total_rooms * $night;
                    $data['total_service_price'] = $value->total_service_price;
                    $data['coupon_amount'] = $value->coupon_amount;
                    $data['sub_total_price'] = $value->sub_total_price;
                    $data['cgst'] = round($value->tax_amount/2, 2);
                    $data['sgst'] = round($value->tax_amount/2, 2);
                    $data['total_order_price'] = $value->total_order_price;
                    $data['created_at'] = $value->created_at;

                    fputcsv($fp, $data);
                }
            }
            fclose($fp);
            return response()->download($csvname)->deleteFileAfterSend(true);
