                    array_push($roomName, 'Total');
                    array_push($roomQty, array_sum($roomQty));
                    $MisData['hotels'][$value] = array_combine($roomName, $roomQty);

                    $MasterInventory = MasterInventory::select('date', DB::raw('SUM(total_booked) as totalBook'))
                        ->where('hotel_id', $key)
                        ->whereBetween('date', [date("Y-m-d", strtotime($start_date)), date("Y-m-d", strtotime($end_date))])
                        ->groupBy('date')
                        ->pluck('totalBook', 'date');
                    foreach ($MasterInventory as $dates => $qty) {
                        if (empty($MisData['data'][$dates])) {
                            foreach ($hotelIds as $hids) {
                                $MisData['data'][$dates][$hids] = 0;
                            }
                        }
                        $MisData['data'][$dates][$key] = $qty;
                    }
                    ksort($MisData['data']);
                    if (!isset($MisData['data'])) {
                        $MisData['data'] = [];
                    }
                    $TotalInventory = MasterInventory::select(DB::raw('SUM(total_booked) as totalBook'), DB::raw('SUM(initial_quantity) as totalAvailable'))
                        ->where('hotel_id', $key)
                        ->whereBetween('date', [date("Y-m-d", strtotime($start_date)), date("Y-m-d", strtotime($end_date))])
                        ->first();
                    if (!empty($TotalInventory)) {
                        $MisData['totBooked'][$key] = !is_null($TotalInventory->totalBook) ? $TotalInventory->totalBook : 0;
                        $MisData['totAvailable'][$key] = !is_null($TotalInventory->totalAvailable) ? $TotalInventory->totalAvailable : 0;
                        $MisData['occupancy'][$key] = ($TotalInventory->totalBook != 0 && $TotalInventory->totalAvailable != 0) ? round(($TotalInventory->totalBook / $TotalInventory->totalAvailable) * 100, 2) : 0;
                    } else {
                        $MisData['totBooked'][$key] = 0;
                        $MisData['totAvailable'][$key] = 0;
                        $MisData['occupancy'][$key] = 0;
                    }
                    $AllAvailable += $MisData['totAvailable'][$key];
                    $AllBooked += $MisData['totBooked'][$key];
                }
                // print_r($MisData);exit;
                foreach($MisData['data'] as $date => $date_data) {
                    foreach($date_data as $hid => $val) {
                        $Rooms = HotelRoom::where(['hotel_id' => $hid, 'status' => 'publish'])->orderBy('price', 'desc')->pluck('quantity', 'id')->toArray();
                        $InvData = DB::table('master_inventory AS MI')
                                ->join('hotel_rooms AS HR', 'MI.room_id', '=', 'HR.id')
                                ->where('MI.date', $date)
                                ->whereIn('MI.room_id', array_keys($Rooms))
                                ->orderBy('HR.price', 'desc')
                                ->pluck('MI.total_booked', 'MI.room_id')
                                ->toArray();
                        if (empty($InvData)) {
                            $InvData = array_map(function ($qty) {
                                return 0;
                            }, $Rooms);
                        }
                        $InvData[$hid.'T'] = $val;
                        $MisData['data'][$date][$hid] = $InvData;
                    }
                }
                $MisData['booked'] = $MisData['occups'] = array();
                foreach($MisData['totBooked'] as $hId => $book_qty) {
                    $Rooms = HotelRoom::where(['hotel_id' => $hId, 'status' => 'publish'])->orderBy('price', 'desc')->pluck('quantity', 'id')->toArray();
                    $bookData = DB::table('master_inventory AS MI')
                            ->join('hotel_rooms AS HR', 'MI.room_id', '=', 'HR.id')
                            ->whereBetween('MI.date', [$start_date, $end_date])
                            ->whereIn('MI.room_id', array_keys($Rooms))
                            ->groupBy('MI.room_id')
                            ->orderBy('HR.price', 'desc')
                            ->pluck(DB::raw('SUM(MI.total_booked) as totBooked'), 'MI.room_id')
                            ->toArray();
                    if (empty($bookData)) {
                        $bookData = array_map(function ($qty) {
                            return 0;
                        }, $Rooms);
                    }
                    $bookData[$hId.'T'] = $book_qty;
                    $MisData['booked']  = array_merge($MisData['booked'], array_values($bookData));

                    $initialData = DB::table('master_inventory AS MI')
                            ->join('hotel_rooms AS HR', 'MI.room_id', '=', 'HR.id')
                            ->whereBetween('MI.date', [$start_date, $end_date])
                            ->whereIn('MI.room_id', array_keys($Rooms))
                            ->groupBy('MI.room_id')
                            ->orderBy('HR.price', 'desc')
                            ->pluck(DB::raw('IFNULL((SUM(MI.total_booked) / SUM(MI.initial_quantity) * 100), 0) as occupancy'), 'MI.room_id')
                            ->toArray();
                    if (empty($initialData)) {
                        $initialData = array_map(function ($qty) {
                            return 0;
                        }, $Rooms);
                    }
                    $initialData[$hId.'T'] = $MisData['occupancy'][$hId];
                    $MisData['occups']  = array_merge($MisData['occups'], array_values($initialData));
                }

                $GrandOccPercent = ($AllAvailable != 0 && $AllBooked != 0) ? round(($AllBooked / $AllAvailable) * 100, 2) : 0;
                $MisData['grandBooked'] = $AllBooked;
                $MisData['grandOcc'] = $GrandOccPercent;

                // print_r($MisData);exit;
                $spreadsheet = new Spreadsheet();
                $sheet = $spreadsheet->getActiveSheet();
                $total_column = count($MisData['hotels']) + 2;


                $sheet->mergeCells('A2:A4');
                $sheet->setCellValueByColumnAndRow(1,2,'Available');
                $j = 2;
                $i = 2;
                $total = 0;
                foreach($MisData['hotels'] as $keys => $x_value) {
                    $hlength = count($x_value) - 1;
                    $sheet->mergeCellsByColumnAndRow($j, 2, ($j + $hlength), 2);
                    $sheet->setCellValueByColumnAndRow($j, 2, $keys);
                    foreach ($x_value as $r_name => $r_qty) {
                        $sheet->setCellValueByColumnAndRow($j,3,$r_name);
                        $sheet->setCellValueByColumnAndRow($j,4,$r_qty);
                        if ($r_name == 'Total') {
                            $total += $r_qty;
                        }
                        $j++;
                    }
                }
                $sheet->mergeCellsByColumnAndRow($j, 2, $j , 3);
                $sheet->setCellValueByColumnAndRow($j,2,'Total');
                $sheet->setCellValueByColumnAndRow($j,4,$total);
                $total_column = $j;
                $sheet->mergeCellsByColumnAndRow(1, 1, $total_column, 1);
                $sheet->setCellValueByColumnAndRow(1,1,'Booking status of properties from ('. $start_date .' - '. $end_date .')');
                $i = 5;
                foreach($MisData['data'] as $dt_key => $sheets_data){
                    $j = 1;
                    $total = 0;
                    $sheet->setCellValueByColumnAndRow($j,$i,date("d.m.Y", strtotime($dt_key)));
                    foreach ($sheets_data as $hid => $r_data) {
                        foreach ($r_data as $rid => $val) {
                            $sheet->setCellValueByColumnAndRow(++$j,$i,$val);
                            if (strpos($rid, 'T')) {
                                $total += $val;
                            }
                        }
                    }
                    $sheet->setCellValueByColumnAndRow($total_column,$i,$total);
                    $i++;
                }
                $sheet->setCellValueByColumnAndRow(1,$i,'TOTAL');
                $j = 1;
                foreach($MisData['booked'] as $keys => $x_value) {
                    $sheet->setCellValueByColumnAndRow(++$j,$i,$x_value);
                }
                $sheet->setCellValueByColumnAndRow($total_column,$i,$MisData['grandBooked']);
                $i++;
                $sheet->setCellValueByColumnAndRow(1,$i,'Occupancy%');
                $j = 1;
                foreach($MisData['occups'] as $keys => $x_value) {
                    $sheet->setCellValueByColumnAndRow(++$j,$i,$x_value);
                }
                $sheet->setCellValueByColumnAndRow($total_column,$i,$MisData['grandOcc']);

                $file_name = 'documents/Daywise_hotel_room_book_report_'. date("d-m-Y h-i-s") .'.xlsx';
                $xsl_name = public_path($file_name);

                $writer = new Xlsx($spreadsheet);
                $writer->save($xsl_name);

                $responce['status'] = 1;
                $responce['file_path'] = $this->site . $file_name;
            }
        }
        echo json_encode($responce);
        exit;
    }

    public function addHotel()
    {
        if (!(parent::checkWritePrivilege(7))) {
            Session::flash('success', 'You are not autherised to do this operation.');
            return redirect()->back();
        }
        $Vendors = User::where('role', '2')->orderBy('company', 'asc')->pluck('company', 'id');
        $Attributes = ServiceAttribute::where('service', 'hotel')->orderBy('name', 'asc')->pluck('name', 'id');
        $HotelAttributes = array();
        foreach ($Attributes as $key => $value) {
            $AttributeValue = AttributeValue::where('attr_id', $key)->orderBy('name', 'asc')->pluck('name', 'id')->toArray();
            $HotelAttributes[$value] = $AttributeValue; //array_values($AttributeValue);
        }
        $CityDetail = City::where(['state_id' => Auth::user()->state])->orderBy('name', 'asc')->pluck('name', 'id')->toArray();

        $SubUser = array();
        if (Auth::user()->role == 2) {
            $SubUserData = User::where('vendor_id', Auth::user()->id)->Where('access_type', '<>', 'agent')->orderBy('first_name', 'asc')->get();
            if (!empty($SubUserData)) {
                foreach ($SubUserData as $value) {
                    $SubUser[$value->id] = $value->first_name . ' ' . $value->last_name;
                }
            }
        }

        return view('hotels.add-hotel', compact('Vendors', 'HotelAttributes', 'CityDetail', 'SubUser'));
    }

    public function hotelAddRequest(Request $request)
    {
        $validate = Validator::make($request->all(), [
            'vender_id' => 'required',
            'name' => 'required|string|min:3|max:100',
            'content' => 'required|string',
            'feature_image' => 'required|mimes:jpeg,png,jpg',
            'banner_image' => 'required|mimes:jpeg,png,jpg',
            'images.*' => 'required|mimes:jpeg,png,jpg',
            'address' => 'required|string',
            'real_address' => 'required|string',
            'city' => 'required|string',
            'place' => 'required|string',
            'check_in_time' => 'required|string',
            'check_out_time' => 'required|string',
            'status' => 'required|string',
            'star_rate' => 'required',
            'terms_conditions' => 'required|string',
            'contact_number' => 'required|digits:10',
            'reception_contact' => 'required|digits:10',
            'contact_email' => 'required|email',
            'gst_applicable' => 'required',
            'show_price' => 'required',
            //                    'gst_number' => 'string',
            //                    'gst_legal_name' => 'string',
            'more_nights' => 'nullable|numeric',
            'foreign_visitors' => 'nullable|numeric',
            'weekend_days' => 'nullable|numeric',
            'week_days' => 'nullable|numeric',
        ]);
        if ($validate->fails()) {
            $errors = $validate->errors();
            return Redirect::to('hotel-add')->withErrors($validate)->withInput();
        } else {
            $UploadDir = 'images/hotels/';
            $gallery_images = array();
            if ($request->hasFile('banner_image')) {
                if ($request->file('banner_image')->isValid()) {
                    $filenameWithExt = str_replace(' ', '-', $request->file('banner_image')->getClientOriginalName());
                    $banner_image = pathinfo($filenameWithExt, PATHINFO_FILENAME) . '_' . time() . '.' . $request->banner_image->extension();
                    $request->banner_image->move(public_path($UploadDir), $banner_image);
                }
            }
            if ($request->hasFile('feature_image')) {
                if ($request->file('feature_image')->isValid()) {
                    $filenameWithExt = str_replace(' ', '-', $request->file('feature_image')->getClientOriginalName());
                    $feature_image = pathinfo($filenameWithExt, PATHINFO_FILENAME) . '_' . time() . '.' . $request->feature_image->extension();
                    $request->feature_image->move(public_path($UploadDir), $feature_image);
                }
            }
            if ($request->hasFile('images')) {
                foreach ($request->file('images') as $file) {
                    $filenameWithExt = str_replace(' ', '-', $file->getClientOriginalName());
                    $gallery_image = pathinfo($filenameWithExt, PATHINFO_FILENAME) . '_' . time() . '.' . $file->extension();
                    $file->move(public_path($UploadDir), $gallery_image);
                    array_push($gallery_images, $UploadDir . $gallery_image);
                }
            }
            $policy = '';
            if (isset($request->policy)) {
                $data = array();
                foreach ($request->policy as $value) {
                    $data[$value['title']] = $value['content'];
                }
                $policy = json_encode($data);
            }
            $slug = str_replace(' ', '-', trim(strtolower($request->name)));
            $AttributeValues = AttributeValue::pluck('icon', 'id');
            $Property = $request->property;
            $property_slug_array = array();
            foreach ($Property as $key1 => $attribute) {
                foreach ($attribute as $key2 => $terms) {
                    $temp = explode('~', $terms);
                    $Property[$key1][$key2] = array('name' => $temp[1], 'icon' => $AttributeValues[$temp[0]]);
                    $property_slug_array[] = $temp[1];
                }
            }
            $add_email = $arr = explode(",", $request->additional_email);
            $add_email = array_filter($add_email, function ($n) { return !empty(trim($n)); });

            $add_phone = $arr = explode(",", $request->additional_phone);
            $add_phone = array_filter($add_phone, function ($n) { return !empty(trim($n)); });

            $Hotel = new MasterHotel([
                'vender_id' => $request->vender_id,
                'name' => trim($request->name),
                'slug' => $slug,
                'content' => addslashes($request->content),
                'feature_image' => $UploadDir . $feature_image,
                'banner_image' => $UploadDir . $banner_image,
                'city' => $request->city,
                'place' => $request->place,
                'address' => addslashes($request->address),
                'real_address' => addslashes($request->real_address),
                'contact_email' => $request->contact_email,
                'manager_name' => $request->manager_name,
                'contact_number' => $request->contact_number,
                'reception_contact' => $request->reception_contact,
                'additional_email' => implode(",", $add_email),
                'additional_phone' => implode(",", $add_phone),
                'map_lat' => $request->map_lat,
                'map_lng' => $request->map_lng,
                'gallery' => json_encode($gallery_images),
                'video' => $request->video,
                'policy' => (empty($policy)) ? json_encode([]) : $policy,
                'star_rate' => $request->star_rate,
                'check_in_time' => date("h:i a", strtotime($request->check_in_time)),
                'check_out_time' => date("h:i a", strtotime($request->check_out_time)),
                'status' => $request->status,
                'create_user' => Auth::user()->id,
                'property' => json_encode($Property),
                'property_slug' => implode("~", $property_slug_array),
                'service_fee' => 0, // $request->service_fee,
                'terms_conditions' => $request->terms_conditions,
                'gst_applicable' => $request->gst_applicable,
                'show_price' => $request->show_price,
                'gst_number' => $request->gst_number,
                'gst_legal_name' => $request->gst_legal_name,
                //                'paytm_mid' => $request->paytm_mid,
                //                'hdfc_mid' => $request->hdfc_mid
                'more_nights' => !empty($request->more_nights) ? $request->more_nights : 0,
                'foreign_visitors' => !empty($request->foreign_visitors) ? $request->foreign_visitors : 0,
                'weekend_days' => !empty($request->weekend_days) ? $request->weekend_days : 0,
                'week_days' => !empty($request->week_days) ? $request->week_days : 0,
            ]);

            if ($Hotel->save()) {
                $HotelId = $Hotel->id;
                if (Auth::user()->role == 2) {
                    if (!empty($request->sub_user)) {
                        $userAccess = array();
                        foreach ($request->sub_user as $value) {
                            $userAccess[] = array(
                                'user_id' => $value,
                                'service' => 'hotel',
                                'service_id' => $HotelId
                            );
                        }
                        DB::table('subuser_access')->insertOrIgnore($userAccess);
                    }
                }

                Session::flash('success', 'Hotel details added successfully.');
                return Redirect::to('all-hotels');
            } else {
                Session::flash('success', 'Unable to add Hotel');
                return Redirect::to('hotel-add');
            }
        }
    }

    public function editHotel($id = null)
    {
        if (!(parent::checkWritePrivilege(7))) {
            Session::flash('success', 'You are not autherised to do this operation.');
            return redirect()->back();
        }
        $HotelDetailsQry = MasterHotel::where('id', $id);
        if (Auth::user()->access_type == 'vendor') {
            $vendor_id = (Auth::user()->role == 2) ? Auth::user()->id : Auth::user()->vendor_id;
            $HotelDetailsQry->where('vender_id', $vendor_id);
        }
        $HotelDetails = $HotelDetailsQry->first();
        if (!empty($HotelDetails)) {
            $HotelDetails->feature_image = $this->site . $HotelDetails->feature_image;
            $HotelDetails->banner_image = $this->site . $HotelDetails->banner_image;
            $HotelDetails->gallery = json_decode($HotelDetails->gallery);
            $property = json_decode($HotelDetails->property, 1);
            $data = array();
            foreach ($property as $key1 => $attribute) {
                foreach ($attribute as $key2 => $terms) {
                    $data[$key1][$key2] = $terms['name'];
                }
            }
            $HotelDetails->property = $data;
            $HotelDetails->policy = json_decode($HotelDetails->policy, 1);
            $gallery = array();
            $count = 1;
            foreach ($HotelDetails->gallery as $value) {
                $gallery[] = ['id' => $count, 'src' => $this->site . $value];
                $count++;
            }
            $gallery = json_encode($gallery);

            $Vendors = User::where('role', '2')->orderBy('company', 'asc')->pluck('company', 'id');
            $Attributes = ServiceAttribute::where('service', 'hotel')->orderBy('name', 'asc')->pluck('name', 'id');
            $HotelAttributes = array();
            foreach ($Attributes as $key => $value) {
                $AttributeValue = AttributeValue::where('attr_id', $key)->orderBy('name', 'asc')->pluck('name', 'id')->toArray();
                $HotelAttributes[$value] = $AttributeValue; // array_values($AttributeValue);
            }
            $CityDetail = City::where(['state_id' => Auth::user()->state])->orderBy('name', 'asc')->pluck('name', 'id')->toArray();

            $SubUser = array();
            if (Auth::user()->role == 2) {
                $SubUserData = User::where('vendor_id', Auth::user()->id)->Where('access_type', '<>', 'agent')->orderBy('first_name', 'asc')->get();
                if (!empty($SubUserData)) {
                    foreach ($SubUserData as $value) {
                        $checked = 0;
                        $SubuserAccess = SubuserAccess::where(['user_id' => $value->id, 'service' => 'hotel', 'service_id' => $id])->first();
                        if (!empty($SubuserAccess)) {
                            $checked = 1;
                        }
                        $SubUser[] = array('id' => $value->id, 'name' => $value->first_name . ' ' . $value->last_name, 'checked' => $checked);
                    }
                }
            }

            return view('hotels.edit-hotel', compact('Vendors', 'HotelAttributes', 'CityDetail', 'HotelDetails', 'gallery', 'SubUser'));
        } else {
            return redirect()->back();
        }
    }

