            }
            $MasterHotel = $HotelDetailsQry->first();
            if (empty($MasterHotel)) {
                return redirect()->back();
            }
            $RoomDetails->image = $this->site . $RoomDetails->image;
            $RoomDetails->gallery = json_decode($RoomDetails->gallery);
            $gallery = array();
            $count = 1;
            if (!empty($RoomDetails->gallery)) {
                foreach ($RoomDetails->gallery as $value) {
                    $gallery[] = ['id' => $count, 'src' => $this->site . $value];
                    $count++;
                }
            }
            $RoomDetails->property = !empty($RoomDetails->property) ? json_decode($RoomDetails->property, 1) : [];
            $gallery = json_encode($gallery);
            $Attributes = RoomAttribute::where('vendor_id', $MasterHotel->vender_id)->orderBy('name', 'asc')->pluck('name', 'id');
            $RoomAttributes = array();
            foreach ($Attributes as $key => $value) {
                $AttributeValue = RoomAttributeValue::where('attr_id', $key)->orderBy('name', 'asc')->pluck('name', 'id')->toArray();
                $RoomAttributes[$value] = $AttributeValue;
            }
            $RoomDetails->mmt_quantity = !empty($RoomDetails->mmt_quantity) ? $RoomDetails->mmt_quantity : 0;

            return view('hotels.edit-room', compact('RoomDetails', 'gallery', 'RoomAttributes'));
        } else {
            return redirect()->back();
        }
    }

