    public function addHotelPricing(Request $request)
    {
        $validate = Validator::make($request->all(), [
            'hotel_id' => 'required|numeric',
            'room_id' => 'required|numeric',
            'room_name' => 'required|string',
            'hotel_name' => 'required|string',
            'price_plan' => 'required|string|unique:hotel_room_pricing',
            'offer_percentage' => 'required|numeric',
            'offer_type' => 'required|string',
            'check_date' => 'required|string'
        ]);
        if ($validate->fails()) {
            $errors = $validate->errors();
            return Redirect::to('manage-hotel-pricing')->withErrors($validate)->withInput();
        } else {
            $check_date = explode(' - ', $request->check_date);
            $start_date = date("Y-m-d", strtotime($check_date[0]));
            $end_date = date("Y-m-d", strtotime($check_date[1]));

            $OldPricing = HotelRoomPricing::where('room_id', $request->room_id)
                ->where('start_date', '>=', $start_date)
                ->where('start_date', '<=', $end_date)
                ->get()->toArray();
            if (empty($OldPricing)) {
                $save_status = 0;
                $MasterHotel = MasterHotel::find($request->hotel_id);
                $HotelRoom = HotelRoom::find($request->room_id);
                // if ($start_date != $end_date) {
                    $difference = strtotime($end_date) - strtotime($start_date);
                    $days = round($difference / (60 * 60 * 24));
                    $Pricing_data = array();

                    for ($i = 0; $i <= $days; $i++) {
                        $roomPrice = $HotelRoom->price;
                        $date = date("Y-m-d", strtotime($start_date . ' + ' . $i . ' days'));
                        $Pricing_data[$i] = [
                            'vendor_id' => $MasterHotel->vender_id,
                            'hotel_id' => $request->hotel_id,
                            'hotel_name' => $request->hotel_name,
                            'room_id' => $request->room_id,
                            'room_name' => $request->room_name,
                            'price_plan' => $request->price_plan,
                            'offer_percentage' => $request->offer_percentage,
                            'offer_type' => $request->offer_type,
                            'start_date' => $date,
                            'end_date' => $request->check_date,
                            'created_by' => Auth::user()->id
                        ];
                        $MasterInventory = MasterInventory::where(['room_id' => $request->room_id, 'date' => $date])->first();
                        if ($request->offer_type == 'minus') {
                            $roomPrice -= $request->offer_percentage;
                        } else {
                            $roomPrice += $request->offer_percentage;
                        }
                        $FullBlockData = BlockedHotel::where(['hotel_id' => $MasterHotel->id, 'block_date' => $date])
                                        ->whereRaw("find_in_set('". $HotelRoom->id ."',rooms)")
                                        ->first();

                        if (!empty($MasterHotel->mmt_hotel_id) && !empty($HotelRoom->mmt_room_id) && !empty($MasterInventory)) {
                            $DataToSend = '';
                            $InvRateplanData = MmtRatePlans::where(['room_type_code' => $HotelRoom->mmt_room_id, 'is_active' => 'true'])->first();
                            if (!empty($InvRateplanData)) {
                                if ($InvRateplanData->rate_plan_code && $HotelRoom->adults > 0) {

                                    $DataToSend .= '<Rate currencyCode="INR" code="'. $InvRateplanData->rate_plan_code .'" rateType="b2c">
                                                <PerOccupancyRates>';
                                    if ($HotelRoom->adults > 1) {
                                        for ($j = 1; $j <= $HotelRoom->adults; $j++) {
                                            $DataToSend .= '<PerOccupancy occupancy="'. $j .'" rate="'. $roomPrice .'" />';
                                        }
                                    } else if ($HotelRoom->adults == 1) {
                                        $DataToSend .= '<PerOccupancy occupancy="1" rate="' . $roomPrice . '" />';
                                    }
                                    $DataToSend .= '</PerOccupancyRates>';
                                    if ($HotelRoom->extra_bed_allowed > 0 && $HotelRoom->extra_bed_price > 0) {
                                        $DataToSend .= '<AdditionalGuestRates>
                                                            <AdditionalGuestRate type="Adult" rate="' . $HotelRoom->extra_bed_price . '" />
                                                            <AdditionalGuestRate type="Child" ageRange="1" rate="0" />
                                                            <AdditionalGuestRate type="Child" ageRange="2" rate="'. $HotelRoom->extra_bed_price .'" />
                                                            <AdditionalGuestRate type="Child" ageRange="3" rate="'. $HotelRoom->extra_bed_price .'" />
                                                        </AdditionalGuestRates>';
                                    }
                                    $DataToSend .= '</Rate>';
                                }
                            }
                            if (!empty($DataToSend)) {
                                $closed = "false";
                                $BlockedMmt = BlockedMmtInventory::where('hotel_id', $MasterHotel->id)
                                            ->where('block_date', $MasterInventory->date)
                                            ->where('rooms', $MasterInventory->room_id)
                                            ->whereRaw("(platform LIKE 'all' OR platform LIKE 'mmt')")
                                            ->get()->toArray();
                                if (!empty($FullBlockData) || !empty($BlockedMmt)) {
                                    $closed = "true";
                                }
                                $Xml = '<?xml version="1.0" encoding="UTF-8" ?>
                                            <AvailRateUpdateRQ hotelCode="'. $MasterHotel->mmt_hotel_id .'" timeStamp="'. time() .'">
                                                <AvailRateUpdate locatorID="1">
                                                    <DateRange from="'. $date . '" to="' . $date .'"/>
                                                    <Availability code="'. $HotelRoom->mmt_room_id .'" count="'. $MasterInventory->total_available .'" closed="'. $closed .'" />
                                                    '. $DataToSend .'
                                                </AvailRateUpdate>
                                            </AvailRateUpdateRQ>';
                                DB::insert("INSERT INTO `mmt_availability_logs`(`request_source`, `vendor_id`, `hotel_id`, `hotel_code`, `room_id`, `room_code`, `request_data`, `status`, `created_at`, `request_type`, `quantity`, `date`) VALUES ('add_hotel_pricing', '". $MasterHotel->vender_id ."', '". $MasterHotel->id ."', '". $MasterHotel->mmt_hotel_id ."', '". $HotelRoom->id ."', '". $HotelRoom->mmt_room_id . "', '". $Xml ."', '0', '". date('Y-m-d H:i:s') ."', 'rate', '". $MasterInventory->total_available ."', '". $MasterInventory->date ."')");
                            }
                        }
                        if (!empty($MasterHotel->ctp_hotel_id) && !empty($HotelRoom->ctp_room_id) && !empty($MasterInventory)) {
                            $DataToSend = '';
                            $InvRateplanData = CtpRatePlans::where(['room_type_code' => $HotelRoom->ctp_room_id])->first();
                            if (!empty($InvRateplanData)) {
                                $base_plan = $additional_plan = '';
                                if ($HotelRoom->adults > 1) {
                                    for ($j = 1; $j <= $HotelRoom->adults; $j++) {
                                        $base_plan .= '<BaseByGuestAmt AgeQualifyingCode="10" NumberOfGuests="'. $j .'" AmountBeforeTax="'. $roomPrice .'"/>';
                                    }
                                } else if ($HotelRoom->adults == 1) {
                                    $base_plan .= '<BaseByGuestAmt AgeQualifyingCode="10" NumberOfGuests="1" AmountBeforeTax="'. $roomPrice .'"/>';
                                }
                                if ($HotelRoom->extra_bed_allowed > 0 && $HotelRoom->extra_bed_price > 0) {
                                    $additional_plan .= '<AdditionalGuestAmounts>
                                                            <AdditionalGuestAmount AgeQualifyingCode="10" Amount="'. $HotelRoom->extra_bed_price .'"/>
                                                            <AdditionalGuestAmount AgeQualifyingCode="8" Amount="'. $HotelRoom->extra_bed_price .'"/>
                                                            <AdditionalGuestAmount AgeQualifyingCode="6" Amount="0"/>
                                                        </AdditionalGuestAmounts>';
                                }
                                $xml = '<OTA_HotelRateAmountNotifRQ xmlns="http://www.opentravel.org/OTA/2003/05" Version="1.0" EchoToken="1234">
                                            <RateAmountMessages HotelCode="'. $MasterHotel->ctp_hotel_id .'">
                                                <RateAmountMessage>
                                                    <StatusApplicationControl Start="'. $date .'" End="'. $date .'" InvTypeCode="'. $HotelRoom->ctp_room_id .'" RatePlanCode="'. $InvRateplanData->rate_plan_code .'" />
                                                    <Rates>
                                                        <Rate>
                                                            <BaseByGuestAmts>
                                                                '. $base_plan .'
                                                            </BaseByGuestAmts>
                                                            '. $additional_plan .'
                                                        </Rate>
                                                    </Rates>
                                                </RateAmountMessage>
                                            </RateAmountMessages>
                                        </OTA_HotelRateAmountNotifRQ>';

                                DB::insert("INSERT INTO `ctp_availability_logs`(`request_source`, `vendor_id`, `hotel_id`, `hotel_code`, `room_id`, `room_code`, `request_data`, `status`, `created_at`, `request_type`, `quantity`, `date`) VALUES ('add_hotel_pricing', '". $MasterHotel->vender_id ."', '". $MasterHotel->id ."', '". $MasterHotel->ctp_hotel_id ."', '". $HotelRoom->id ."', '". $HotelRoom->ctp_room_id . "', '". $xml ."', '0', '". date('Y-m-d H:i:s') ."', 'rate', '". $MasterInventory->total_available ."', '". $MasterInventory->date ."')");
                            }
                        }
                    }
                    $save_status = HotelRoomPricing::insert($Pricing_data);
                // } else {
                //     $HotelPricing = new HotelRoomPricing([
                //         'hotel_id' => $request->hotel_id,
                //         'hotel_name' => $request->hotel_name,
                //         'room_id' => $request->room_id,
                //         'room_name' => $request->room_name,
                //         'price_plan' => $request->price_plan,
                //         'offer_percentage' => $request->offer_percentage,
                //         'offer_type' => $request->offer_type,
                //         'start_date' => $start_date,
                //         'end_date' => $request->check_date,
                //         'created_by' => Auth::user()->id
                //     ]);
                //     $save_status = $HotelPricing->save();
                // }
                if ($save_status) {
                    Session::flash('success', 'Hotel Pricing saved successful.');
                    return Redirect::to('hotel-room-pricing');
                } else {
                    Session::flash('success', 'Unable to add pricing.');
                    return Redirect::to('manage-hotel-pricing');
                }
            } else {
                Session::flash('success', 'There is already a pricing present on this date. please change the date and try again!');
                return Redirect::to('manage-hotel-pricing');
            }
        }
    }

