    public function getBlockData(Request $request)
    {

        $aColumns = array('id', 'hotel_name', 'room_name', 'quantity', 'block_reason', 'block_date');
        $sIndexColumn = "id";
        $sTable = "hotel_availability";
        /*
         * Paging
         */
        $sLimit = "";
        if (isset($_POST['start']) && $_POST['length'] != '-1') {
            $sLimit = "LIMIT " . intval($_POST['start']) . ", " . intval($_POST['length']);
        }
        /*
         * Ordering
         */
        $sOrder = " ORDER BY id DESC ";
        if (isset($_POST['order'])) {
            $sOrder = "ORDER BY ";
            for ($i = 0; $i < intval(count($_POST['order'])); $i++) {
                if ($_POST['columns'][$_POST['order'][$i]['column']]['orderable'] == "true") {
                    $sOrder .= "`" . $aColumns[intval($_POST['order'][$i]['column'])] . "` " .
                        ($_POST['order'][$i]['dir'] === 'asc' ? 'asc' : 'desc') . ", ";
                }
            }
            $sOrder = substr_replace($sOrder, "", -2);
            if ($sOrder == "ORDER BY") {
                $sOrder = "";
            }
        }
        /*
         * Filtering
         * NOTE this does not match the built-in DataTables filtering which does it
         * word by word on any field. It's possible to do here, but concerned about efficiency
         * on very large tables, and MySQL's regex functionality is very limited
         */
        $vender_id = (Auth::user()->role == 2) ? Auth::user()->id : Auth::user()->vendor_id;
        $vendor_condtition = ' AND `vendor_id` = '. $vender_id;
        if ($vender_id == 3) {
            $vendor_condtition .= ' AND `created_at` > "'. $this->ecoStartDate .'" ';
        }
        $sWhere = 'WHERE status = 1 '. $vendor_condtition;
        if ((Auth::user()->role == 3)) {
            $SubuserAccess = SubuserAccess::where(['user_id' => Auth::user()->id, 'service' => 'hotel'])->pluck('service_id', 'id')->toArray();
            if (!empty($SubuserAccess)) {
                $sWhere .= ' AND hotel_id in (' . implode(',', $SubuserAccess) . ')';
            }
        }
        if (!empty($_POST['searchValue1']) || !empty($_POST['searchValue2']) || !empty($_POST['searchValue3'])) {
            $condition1 = '';
            $condition2 = '';
            $condition3 = '';
            if (!empty($_POST['searchValue1'])) {
                $_POST['searchValue1'] = parent::cleanString($_POST['searchValue1']);
                $condition1 .= ' AND hotel_id = "' . $_POST['searchValue1'] . '"';
            }
            if (!empty($_POST['searchValue2'])) {
                $_POST['searchValue2'] = parent::cleanString($_POST['searchValue2']);
                $condition2 .= ' AND room_id = "' . $_POST['searchValue2'] . '"';
            }
            // if (!empty($_POST['searchValue3'])) {
            //     $condition3 .= ' AND block_date = "' . date("Y-m-d", strtotime($_POST['searchValue3'])) . '"';
            // }
            if (!empty($_POST['searchValue3'])) {
                $check_date = explode(' - ', $_POST['searchValue3']);
                $condition3 .= ' AND block_date BETWEEN "' . date("Y-m-d", strtotime($check_date[0])) . '" AND "' . date("Y-m-d", strtotime($check_date[1])) . '"';
            }
            $sWhere .= $condition1 . $condition2 . $condition3;
        }
        if (isset($_POST['search']['value']) && $_POST['search']['value'] != "") {
            $sWhere .= " AND (";
            for ($i = 0; $i < count($aColumns); $i++) {
                $sWhere .= "`" . $aColumns[$i] . "` LIKE '%" . $_POST['search']['value'] . "%' OR ";
            }
            $sWhere = substr_replace($sWhere, "", -3);
            $sWhere .= ')';
        }

        /* Individual column filtering */
        for ($i = 0; $i < count($aColumns); $i++) {
            if (isset($_POST['bSearchable_' . $i]) && $_POST['bSearchable_' . $i] == "true" && $_POST['sSearch_' . $i] != '') {
                if ($sWhere == "") {
                    $sWhere = "WHERE ";
                } else {
                    $sWhere .= " AND ";
                }
                $sWhere .= "`" . $aColumns[$i] . "` LIKE '%" . $_POST['sSearch_' . $i] . "%' ";
            }
        }

        /*
         * SQL queries
         * Get data to display
         */
        $exQuery = "SELECT * FROM $sTable $sWhere $sOrder";
        $sQuery = "SELECT SQL_CALC_FOUND_ROWS * FROM   $sTable $sWhere $sOrder $sLimit";
        //        echo $sQuery;exit;
        $rResult = DB::select($sQuery);

        /* Data set length after filtering */
        $sQuery = "SELECT FOUND_ROWS() as totalrow";
        $aResultFilterTotal = DB::select($sQuery);
        $iFilteredTotal = $aResultFilterTotal[0]->totalrow;
        /* Total data set length */
        $sQuery = "SELECT COUNT(`" . $sIndexColumn . "`) as countindex FROM $sTable $sWhere";
        $aResultTotal = DB::select($sQuery);
        $iTotal = $aResultTotal[0]->countindex;

        /*
         * Output
         */
        $output = array(
            "draw" => intval($_POST['draw']),
            "recordsTotal" => $iTotal,
            "recordsFiltered" => $iFilteredTotal,
            "data" => array()
        );

        foreach ($rResult as $aRow) {
            $row = array();

            $row[] = '<div class="checkbox-fade fade-in-primary"><label><input type="checkbox" value="' . $aRow->id . '" class="itemcheck"><span class="cr"><i class="cr-icon icofont icofont-ui-check txt-primary"></i></span></label></div>';
            $row[] = $aRow->hotel_name;
            $row[] = $aRow->room_name;
            $row[] = $aRow->quantity;
            $row[] = $aRow->block_reason;
            $row[] = date("d-M-Y", strtotime($aRow->block_date));
            $row[] = '<div class="btn-group">
                <button aria-expanded="false" data-toggle="dropdown" class="btn btn-info btn-xs btn-outline dropdown-toggle waves-effect waves-light" type="button">Action <span class="caret"></span></button>
                <ul role="menu" class="dropdown-menu">
                    <li><a href="javascript:void(0);" class="modify-status" data-id="' . $aRow->id . '" data-status="2">Mark as Booked</a></li>
                    <li><a href="javascript:void(0);" class="modify-status" data-id="' . $aRow->id . '" data-status="0">Mark as Released</a></li>
                </ul>
            </div>';
            //            $row[] = ($aRow->status == '1') ? '<span style="text-transform: capitalize;font-size: 12px;color: #fff;background-color: #717171;font-weight: 700;border-radius: 0.25rem;padding: 0.25em 0.4em;">Blocked</span>' : '<span style="background-color: #28a745;font-size: 12px;font-weight: 700;border-radius: 0.25rem;padding: 0.25em 0.4em;color: #fff;text-transform: capitalize;">Available</span>';

            //            <li><a href="javascript:void(0);" class="change-status" data-id="'. $aRow->id .'" data-status="'. $aRow->status .'">'. $status .'</a></li>
            $output['data'][] = $row;
        }
        $output['exportQuery'] = $exQuery;

        echo json_encode($output);
        exit;
    }

    public function blockHotelRoom()
    {
        if (!(parent::checkWritePrivilege(12))) {
            Session::flash('success', 'You are not autherised to do this operation.');
            return redirect()->back();
        }
        $vender_id = (Auth::user()->role == 2) ? Auth::user()->id : Auth::user()->vendor_id;
        $MasterHotelQuery = MasterHotel::where('status', 'publish')->where('vender_id', $vender_id);
        if ((Auth::user()->role == 3)) {
            $SubuserAccess = SubuserAccess::where(['user_id' => Auth::user()->id, 'service' => 'hotel'])->pluck('service_id', 'id')->toArray();
            if (!empty($SubuserAccess)) {
                $MasterHotelQuery->whereIn('id', array_values($SubuserAccess));
            }
        }
        $MasterHotel = $MasterHotelQuery->orderBy('name', 'ASC')->pluck('name', 'id')->toArray();
        $hotelHtml = '';
        foreach ($MasterHotel as $key => $value) {
            $hotelHtml .= '<option value="' . $key . '">' . $value . '</option>';
        }
        $Maxdates = DB::table('master_inventory')
                    ->whereIn('hotel_id', array_keys($MasterHotel))
                    ->groupBy('hotel_id')
                    ->pluck(DB::raw('MAX(date) AS date'), 'hotel_id')
                    ->toArray();
        $MaxDateArr = json_encode($Maxdates);

        return view('hotels.block-hotel-room', compact('MasterHotel', 'hotelHtml', 'MaxDateArr'));
    }

    public function blockHotelRoomRequest(Request $request)
    {
        if ($request->block_type == 'single') {
            $validate = Validator::make($request->all(), [
                'hotel_id' => 'required|numeric',
                'room_id' => 'required|numeric',
                'room_name' => 'required|string',
                'hotel_name' => 'required|string',
                'block_date' => 'required|string',
                'block_reason' => 'required|string',
                'quantity' => 'required|numeric|min:1'
            ]);
            if ($validate->fails()) {
                $errors = $validate->errors();
                return Redirect::to('block-hotel-room')->withErrors($validate)->withInput();
            } else {
                $block_date = explode(" - ", $request->block_date);
                $start_date = date("Y-m-d", strtotime($block_date['0']));
                $end_date = date("Y-m-d", strtotime($block_date['1']));
                $OrderData = MasterInventory::where('room_id', $request->room_id)
                    ->whereBetween('date', [$start_date, $end_date])
                    ->get();
                if (!empty($OrderData)) {
                    $MasterHotel = MasterHotel::find($request->hotel_id);
                    if (!empty($MasterHotel)) {
                        $HotelRoom = HotelRoom::find($request->room_id);
                        $status = 0;
                        foreach ($OrderData as $value) {
                            $MasterInventory = MasterInventory::where(['room_id' => $request->room_id, 'date' => $value->date])->first();
                            if (!empty($MasterInventory) && $MasterInventory->total_available > 0) {
                                $block_qty = ($MasterInventory->total_available >= $request->quantity) ? $request->quantity : $MasterInventory->total_available;
                                $MasterInventory->total_available -= $block_qty;
                                $MasterInventory->total_blocked += $block_qty;
                                $MasterInventory->save();

                                $HotelAvailability = new HotelAvailability([
                                    'vendor_id' => $MasterHotel->vender_id,
                                    'hotel_id' => $request->hotel_id,
                                    'hotel_name' => $request->hotel_name,
                                    'room_id' => $request->room_id,
                                    'room_name' => $request->room_name,
                                    'block_date' => $value->date,
                                    'block_reason' => $request->block_reason,
                                    'quantity' => $block_qty,
                                    'created_by' => Auth::user()->id,
                                    'status' => 1
                                ]);
                                if ($HotelAvailability->save()) {
                                    $status = 1;
                                    // parent::updateMmtInventory($MasterHotel->vender_id, $MasterHotel->id);
                                    $FullBlockData = BlockedHotel::where(['hotel_id' => $MasterHotel->id, 'block_date' => $MasterInventory->date])
                                                    ->whereRaw("find_in_set('". $HotelRoom->id ."',rooms)")
                                                    ->first();
                                    if (!empty($MasterHotel->mmt_hotel_id) && !empty($HotelRoom->mmt_room_id)) {
                                        $BlockedMmt = BlockedMmtInventory::where('hotel_id', $MasterHotel->id)
                                                    ->where('block_date', $MasterInventory->date)
                                                    ->where('rooms', $MasterInventory->room_id)
                                                    ->whereRaw("(platform LIKE 'all' OR platform LIKE 'mmt')")
                                                    ->get()->toArray();
                                        $closed = 'false';
                                        if (!empty($FullBlockData) || !empty($BlockedMmt)) {
                                            $closed = "true";
                                        }
                                        $Xml = '<?xml version="1.0" encoding="UTF-8" ?>
                                                    <AvailRateUpdateRQ hotelCode="'. $MasterHotel->mmt_hotel_id .'" timeStamp="'. time() .'">
                                                        <AvailRateUpdate locatorID="1">
                                                            <DateRange from="'. $value->date . '" to="' . $value->date .'"/>
                                                            <Availability code="'. $HotelRoom->mmt_room_id .'" count="'. $MasterInventory->total_available .'" closed="'. $closed .'" />
                                                        </AvailRateUpdate>
                                                    </AvailRateUpdateRQ>';
                                        DB::insert("INSERT INTO `mmt_availability_logs`(`request_source`, `vendor_id`, `hotel_id`, `hotel_code`, `room_id`, `room_code`, `request_data`, `status`, `created_at`, `request_type`, `quantity`, `date`) VALUES ('inventory_block_web', '". $MasterHotel->vender_id ."', '". $MasterHotel->id ."', '". $MasterHotel->mmt_hotel_id ."', '". $HotelRoom->id ."', '". $HotelRoom->mmt_room_id . "', '". $Xml ."', '0', '". date('Y-m-d H:i:s') ."', 'inventory', '". $MasterInventory->total_available ."', '". $MasterInventory->date ."')");
                                    }
                                    if (!empty($MasterHotel->ctp_hotel_id) && !empty($HotelRoom->ctp_room_id)) {
                                        $BlockedMmt = BlockedMmtInventory::where('hotel_id', $MasterHotel->id)
                                                    ->where('block_date', $MasterInventory->date)
                                                    ->where('rooms', $MasterInventory->room_id)
                                                    ->whereRaw("(platform LIKE 'all' OR platform LIKE 'cleartrip')")
                                                    ->get()->toArray();
                                        $closed = 'Open';
                                        if (!empty($FullBlockData) || !empty($BlockedMmt)) {
                                            $closed = "Close";
                                        }
                                        $InvRateplanData = CtpRatePlans::where(['room_type_code' => $HotelRoom->ctp_room_id])->first();
                                        if (!empty($InvRateplanData)) {
                                            // Availability
                                            $Xml = '<OTA_HotelAvailNotifRQ xmlns="http://www.opentravel.org/OTA/2003/05" Version="1.0" EchoToken="1234">
                                                        <AvailStatusMessages HotelCode="'. $MasterHotel->ctp_hotel_id .'">
                                                        <AvailStatusMessage BookingLimit="'. $MasterInventory->total_available .'">
                                                            <StatusApplicationControl Start="'. $value->date .'" End="'. $value->date .'" InvTypeCode="'. $HotelRoom->ctp_room_id .'" RatePlanCode="'. $InvRateplanData->rate_plan_code .'" />
                                                            <RestrictionStatus Status="'. $closed .'" />
                                                        </AvailStatusMessage>
                                                        </AvailStatusMessages>
                                                    </OTA_HotelAvailNotifRQ>';
                                            DB::insert("INSERT INTO `ctp_availability_logs`(`request_source`, `vendor_id`, `hotel_id`, `hotel_code`, `room_id`, `room_code`, `request_data`, `status`, `created_at`, `request_type`, `quantity`, `date`) VALUES ('inventory_block_web', '". $MasterHotel->vender_id ."', '". $MasterHotel->id ."', '". $MasterHotel->ctp_hotel_id ."', '". $HotelRoom->id ."', '". $HotelRoom->ctp_room_id . "', '". $Xml ."', '0', '". date('Y-m-d H:i:s') ."', 'inventory', '". $MasterInventory->total_available ."', '". $MasterInventory->date ."')");
                                        }
                                    }
                                }
                            }
                        }
                        if ($status == 1) {
                            Session::flash('success', 'Hotel room blocked successful.');
                            return Redirect::to('hotel-room-block-data');
                        } else {
                            Session::flash('success', 'Unable to block room. please try again.');
                            return Redirect::to('block-hotel-room');
                        }
                    } else {
                        Session::flash('success', 'Unable to block room. please try again.');
                        return Redirect::to('block-hotel-room');
                    }
                } else {
                    Session::flash('success', 'Unable to block room.');
                    return Redirect::to('block-hotel-room');
                }
            }
        } elseif ($request->block_type == 'multiple') {
            $hotel = $request->hotel_id;
            $rooms = $request->room_id;
            $check_date = explode(' - ', $request->block_date);
            $block_st_date = date("Y-m-d", strtotime($check_date[0]));
            $block_end_date = date("Y-m-d", strtotime($check_date[1]));
            $BlockedHotels = BlockedHotel::where('hotel_id', $hotel)
                ->whereBetween('block_date', [$block_st_date, $block_end_date])
                ->where(function ($query) use ($rooms) {
                    foreach ($rooms as $value) {
                        $query->orWhereRaw("find_in_set('" . $value . "',rooms)");
                    }
                })
                ->get()->toArray();
            if (empty($BlockedHotels)) {
                $Blocked_data = array();
                $key = 0;
                $MasterHotel = MasterHotel::find($hotel);
                $tmp_date = $block_st_date;
                while ($tmp_date <= $block_end_date) {
                    $Blocked_data[$key] = [
                        'vendor_id' => $MasterHotel->vender_id,
                        'hotel_id' => $hotel,
                        'hotel_name' => $MasterHotel->name,
                        'rooms' => implode(',', $rooms),
                        'block_date' => date("Y-m-d", strtotime($tmp_date)),
                        'block_reason' => $request->block_reason,
                        'created_by' => Auth::user()->id
                    ];
                    foreach ($rooms as $roomId) {
                        $HotelRoom = HotelRoom::find($roomId);
                        $MasterInventory = MasterInventory::where(['room_id' => $roomId, 'date' => date("Y-m-d", strtotime($tmp_date))])->first();
                        if (!empty($MasterHotel->mmt_hotel_id) && !empty($HotelRoom->mmt_room_id) && !empty($MasterInventory)) {
                            $Xml = '<?xml version="1.0" encoding="UTF-8" ?>
                                        <AvailRateUpdateRQ hotelCode="'. $MasterHotel->mmt_hotel_id .'" timeStamp="'. time() .'">
                                            <AvailRateUpdate locatorID="1">
                                                <DateRange from="'. $tmp_date . '" to="' . $tmp_date .'"/>
                                                <Availability code="'. $HotelRoom->mmt_room_id .'" count="'. $MasterInventory->total_available .'" closed="true" />
                                            </AvailRateUpdate>
                                        </AvailRateUpdateRQ>';
                            DB::insert("INSERT INTO `mmt_availability_logs`(`request_source`, `vendor_id`, `hotel_id`, `hotel_code`, `room_id`, `room_code`, `request_data`, `status`, `created_at`, `request_type`, `quantity`, `date`) VALUES ('full_block_web', '". $MasterHotel->vender_id ."', '". $MasterHotel->id ."', '". $MasterHotel->mmt_hotel_id ."', '". $HotelRoom->id ."', '". $HotelRoom->mmt_room_id . "', '". $Xml ."', '0', '". date('Y-m-d H:i:s') ."', 'inventory', '". $MasterInventory->total_available ."', '". $MasterInventory->date ."')");
                        }
                        if (!empty($MasterHotel->ctp_hotel_id) && !empty($HotelRoom->ctp_room_id) && !empty($MasterInventory)) {
                            $InvRateplanData = CtpRatePlans::where(['room_type_code' => $HotelRoom->ctp_room_id])->first();
                            if (!empty($InvRateplanData)) {
                                // Availability
                                $Xml = '<OTA_HotelAvailNotifRQ xmlns="http://www.opentravel.org/OTA/2003/05" Version="1.0" EchoToken="1234">
                                            <AvailStatusMessages HotelCode="'. $MasterHotel->ctp_hotel_id .'">
                                            <AvailStatusMessage BookingLimit="'. $MasterInventory->total_available .'">
                                                <StatusApplicationControl Start="'. $tmp_date .'" End="'. $tmp_date .'" InvTypeCode="'. $HotelRoom->ctp_room_id .'" RatePlanCode="'. $InvRateplanData->rate_plan_code .'" />
                                                <RestrictionStatus Status="Close" />
                                            </AvailStatusMessage>
                                            </AvailStatusMessages>
                                        </OTA_HotelAvailNotifRQ>';
                                DB::insert("INSERT INTO `ctp_availability_logs`(`request_source`, `vendor_id`, `hotel_id`, `hotel_code`, `room_id`, `room_code`, `request_data`, `status`, `created_at`, `request_type`, `quantity`, `date`) VALUES ('full_block_web', '". $MasterHotel->vender_id ."', '". $MasterHotel->id ."', '". $MasterHotel->ctp_hotel_id ."', '". $HotelRoom->id ."', '". $HotelRoom->ctp_room_id . "', '". $Xml ."', '0', '". date('Y-m-d H:i:s') ."', 'inventory', '". $MasterInventory->total_available ."', '". $MasterInventory->date ."')");
                            }
                        }
                    }
                    $key++;
                    $tmp_date = date("Y-m-d", strtotime($tmp_date . ' + 1 day'));
                }
                $save_status = BlockedHotel::insert($Blocked_data);
                if ($save_status) {
                    $vender_id = (Auth::user()->role == 2) ? Auth::user()->id : Auth::user()->vendor_id;
                    // parent::updateMmtInventory($vender_id);

                    Session::flash('success', 'Hotels blocked successfully.');
                    return Redirect::to('blocked-hotels');
                } else {
                    Session::flash('success', 'Unable to block Hotel.');
                    return Redirect::to('block-hotel-room');
                }
            } else {
                Session::flash('success', 'Selected hotel rooms are already blocked for this date. please change date and try again.');
                return Redirect::to('block-hotel-room');
            }
        } elseif ($request->block_type == 'future') {
            $validate = Validator::make($request->all(), [
                'hotel_id' => 'required|numeric',
                'block_date' => 'required|string',
                'block_reason' => 'required|string',
            ]);
            if ($validate->fails()) {
                $errors = $validate->errors();
                return Redirect::to('block-hotel-room')->withErrors($validate)->withInput();
            } else {
                $check_date = explode(' - ', $request->block_date);
                $block_st_date = date("Y-m-d", strtotime($check_date[0]));
                $block_end_date = date("Y-m-d", strtotime($check_date[1]));
                $roomIds = ($request->room_id);
                sort($roomIds);
                // $request->room_id = sort($request->room_id);
                $room_qty_array = array_combine($roomIds, $request->room_quantity);
                // echo "<pre>";print_r($request->all());print_r($room_qty_array);exit;
                $BlockData = array();
                $MasterHotel = MasterHotel::find($request->hotel_id);
                foreach ($room_qty_array as $key => $value) {
                    $HotelRoom = HotelRoom::find($key);
                    $tmp_date = $block_st_date;
                    while ($tmp_date <= $block_end_date) {
                        $ExistBlock = HotelAvailability::select(DB::raw('SUM(quantity) AS totBlocked'))->where(['room_id' => $key, 'block_date' => $tmp_date])->first();
                        $totBlocked = (!empty($ExistBlock->totBlocked)) ? $ExistBlock->totBlocked : 0;
                        if (($totBlocked + $value) <= $HotelRoom->quantity) {
                            $BlockData[] = array(
                                'vendor_id' => $MasterHotel->vender_id,
                                'hotel_id' => $request->hotel_id,
                                'hotel_name' => $MasterHotel->name,
                                'room_id' => $key,
                                'room_name' => $HotelRoom->title,
                                'block_date' => $tmp_date,
                                'block_reason' => $request->block_reason,
                                'quantity' => $value,
                                'created_by' => Auth::user()->id,
                                'status' => 1
                            );
                            $tmp_date = date("Y-m-d", strtotime($tmp_date . ' + 1 day'));
                        } else {
                            Session::flash('success', 'Sorry, Maximum ' . $HotelRoom->quantity . ' ' . $HotelRoom->title . ' rooms can be blocked. please try again.');
                            return Redirect::to('block-hotel-room');
                        }
                    }
                }
                $save_status = HotelAvailability::insert($BlockData);

                if ($save_status) {
                    // parent::updateMmtInventory($vender_id);

                    Session::flash('success', 'Hotel rooms blocked successfully.');
                    return Redirect::to('hotel-room-block-data');
                } else {
                    Session::flash('success', 'Unable to block Hotel inventory.');
                    return Redirect::to('block-hotel-room');
                }
            }
        }
    }

    public function blockedHotels()
    {
        if (!(parent::checkViewPrivilege(12))) {
            Session::flash('success', 'You are not autherised to view this page.');
            return redirect()->back();
        }
        $vender_id = (Auth::user()->role == 2) ? Auth::user()->id : Auth::user()->vendor_id;
        $MasterHotelQuery = MasterHotel::where('status', 'publish')->where('vender_id', $vender_id);
        if ((Auth::user()->role == 3)) {
            $SubuserAccess = SubuserAccess::where(['user_id' => Auth::user()->id, 'service' => 'hotel'])->pluck('service_id', 'id')->toArray();
            if (!empty($SubuserAccess)) {
                $MasterHotelQuery->whereIn('id', array_values($SubuserAccess));
            }
        }
        $MasterHotel = $MasterHotelQuery->orderBy('name', 'ASC')->pluck('name', 'id');
        $hotelHtml = '';
        foreach ($MasterHotel as $key => $value) {
            $hotelHtml .= '<option value="' . $key . '">' . $value . '</option>';
        }

        return view('hotels.blocked-hotels', compact('MasterHotel', 'hotelHtml'));
    }

    public function getBlockedHotels(Request $request)
    {

        $aColumns = array('hotel_name', 'rooms', 'block_date', 'block_reason', 'id');
        $sIndexColumn = "id";
        $sTable = "blocked_hotels";
        /*
         * Paging
         */
        $sLimit = "";
        if (isset($_POST['start']) && $_POST['length'] != '-1') {
            $sLimit = "LIMIT " . intval($_POST['start']) . ", " . intval($_POST['length']);
        }
        /*
         * Ordering
         */
        $sOrder = " ORDER BY id DESC ";
        if (isset($_POST['order'])) {
            $sOrder = "ORDER BY ";
            for ($i = 0; $i < intval(count($_POST['order'])); $i++) {
                if ($_POST['columns'][$_POST['order'][$i]['column']]['orderable'] == "true") {
                    $sOrder .= "`" . $aColumns[intval($_POST['order'][$i]['column'])] . "` " .
                        ($_POST['order'][$i]['dir'] === 'asc' ? 'asc' : 'desc') . ", ";
                }
            }
            $sOrder = substr_replace($sOrder, "", -2);
            if ($sOrder == "ORDER BY") {
                $sOrder = "";
            }
        }
        /*
         * Filtering
         * NOTE this does not match the built-in DataTables filtering which does it
         * word by word on any field. It's possible to do here, but concerned about efficiency
         * on very large tables, and MySQL's regex functionality is very limited
         */
        $vender_id = (Auth::user()->role == 2) ? Auth::user()->id : Auth::user()->vendor_id;
        $sWhere = 'WHERE `vendor_id` = ' . $vender_id;
        if ($vender_id == 3) {
            $sWhere .= ' AND `created_at` > "'. $this->ecoStartDate .'" ';
        }
        if ((Auth::user()->role == 3)) {
            $SubuserAccess = SubuserAccess::where(['user_id' => Auth::user()->id, 'service' => 'hotel'])->pluck('service_id', 'id')->toArray();
            if (!empty($SubuserAccess)) {
                $sWhere .= ' AND hotel_id in (' . implode(',', $SubuserAccess) . ')';
            }
        }

        if (!empty($_POST['searchValue1']) || !empty($_POST['searchValue2']) || !empty($_POST['searchValue3'])) {
            $condition1 = '';
            $condition2 = '';
            if (!empty($_POST['searchValue1'])) {
                $_POST['searchValue1'] = parent::cleanString($_POST['searchValue1']);
                $condition1 .= ' AND hotel_id = "' . $_POST['searchValue1'] . '"';
            }
            if (!empty($_POST['searchValue2'])) {
                $check_date = explode(' - ', $_POST['searchValue2']);
                $condition2 .= ' AND block_date BETWEEN "' . date("Y-m-d", strtotime($check_date[0])) . '" AND "' . date("Y-m-d", strtotime($check_date[1])) . '"';
            }

            $sWhere .= $condition1 . $condition2;
        }

        if (isset($_POST['search']['value']) && $_POST['search']['value'] != "") {
            $sWhere .= " AND (";
            for ($i = 0; $i < count($aColumns); $i++) {
                $sWhere .= "`" . $aColumns[$i] . "` LIKE '%" . $_POST['search']['value'] . "%' OR ";
            }
            $sWhere = substr_replace($sWhere, "", -3);
            $sWhere .= ')';
        }

        /* Individual column filtering */
        for ($i = 0; $i < count($aColumns); $i++) {
            if (isset($_POST['bSearchable_' . $i]) && $_POST['bSearchable_' . $i] == "true" && $_POST['sSearch_' . $i] != '') {
                if ($sWhere == "") {
                    $sWhere = "WHERE ";
                } else {
                    $sWhere .= " AND ";
                }
                $sWhere .= "`" . $aColumns[$i] . "` LIKE '%" . $_POST['sSearch_' . $i] . "%' ";
            }
        }

        /*
         * SQL queries
         * Get data to display
         */
        $sQuery = "SELECT SQL_CALC_FOUND_ROWS * FROM   $sTable $sWhere $sOrder $sLimit";
        // echo $sQuery;exit;
        $rResult = DB::select($sQuery);

        /* Data set length after filtering */
        $sQuery = "SELECT FOUND_ROWS() as totalrow";
        $aResultFilterTotal = DB::select($sQuery);
        $iFilteredTotal = $aResultFilterTotal[0]->totalrow;
        /* Total data set length */
        $sQuery = "SELECT COUNT(`" . $sIndexColumn . "`) as countindex FROM $sTable $sWhere";
        $aResultTotal = DB::select($sQuery);
        $iTotal = $aResultTotal[0]->countindex;

        /*
         * Output
         */
        $output = array(
            "draw" => intval($_POST['draw']),
            "recordsTotal" => $iTotal,
            "recordsFiltered" => $iFilteredTotal,
            "data" => array()
        );

        foreach ($rResult as $aRow) {
            $row = array();

            // $UserData = User::find($aRow->created_by);
            $HotelRoom = HotelRoom::whereIn('id', explode(',', $aRow->rooms))->pluck('title')->toArray();

            $row[] = '<div class="checkbox-fade fade-in-primary"><label><input type="checkbox" value="' . $aRow->id . '" class="itemcheck"><span class="cr"><i class="cr-icon icofont icofont-ui-check txt-primary"></i></span></label></div>';
            $row[] = $aRow->hotel_name;
            $row[] = implode(', ', $HotelRoom);
            $row[] = date("M d Y", strtotime($aRow->block_date));
            $row[] = $aRow->block_reason;
            // $row[] = $UserData->first_name . ' ' . $UserData->last_name;
            $row[] = '<div class="btn-group">
                <button aria-expanded="false" data-toggle="dropdown" class="btn btn-info btn-xs btn-outline dropdown-toggle waves-effect waves-light" type="button">Action <span class="caret"></span></button>
                <ul role="menu" class="dropdown-menu">
                    <li><a href="javascript:void(0);" class="delete-data" data-id="' . $aRow->id . '">Delete</a></li>
                </ul>
            </div>';
            //            <li><a href="javascript:void(0);" class="change-status" data-id="'. $aRow->id .'" data-status="'. $aRow->status .'">'. $status .'</a></li>
            $output['data'][] = $row;
        }

        echo json_encode($output);
        exit;
    }

