            $row[] = '<div class="checkbox-fade fade-in-primary"><label><input type="checkbox" value="' . $aRow->id . '" class="itemcheck"><span class="cr"><i class="cr-icon icofont icofont-ui-check txt-primary"></i></span></label></div>';
            $row[] = $aRow->hotel_name;
            // $row[] = $aRow->room_name;
            $row[] = date("M d Y", strtotime($aRow->start_date));
            $row[] = date("M d Y", strtotime($aRow->end_date));
            // $row[] = '<div class="btn-group">
            //     <button aria-expanded="false" data-toggle="dropdown" class="btn btn-info btn-xs btn-outline dropdown-toggle waves-effect waves-light" type="button">Action <span class="caret"></span></button>
            //     <ul role="menu" class="dropdown-menu">
            //         <li><a class="delete-data" data-id="' . $aRow->id . '">Delete</a></li>
            //     </ul>
            // </div>';
            $row[] = '<a class="delete-data" data-id="' . $aRow->id . '">Delete</a>';
            //            <li><a href="javascript:void(0);" class="change-status" data-id="'. $aRow->id .'" data-status="'. $aRow->status .'">'. $status .'</a></li>
            $output['data'][] = $row;
        }

        echo json_encode($output);
        exit;
    }

    public function addSalesData()
    {
        if (!(parent::checkWritePrivilege(13))) {
            Session::flash('success', 'You are not autherised to do this operation.');
            return redirect()->back();
        }
        $vender_id = (Auth::user()->role == 2) ? Auth::user()->id : Auth::user()->vendor_id;
        $MasterHotelQuery = MasterHotel::where('status', 'publish')->where('vender_id', $vender_id);
        if ((Auth::user()->role == 3)) {
            $SubuserAccess = SubuserAccess::where(['user_id' => Auth::user()->id, 'service' => 'hotel'])->pluck('service_id', 'id')->toArray();
            if (!empty($SubuserAccess)) {
                $MasterHotelQuery->whereIn('id', array_values($SubuserAccess));
            }
        }
        $MasterHotel = $MasterHotelQuery->orderBy('name', 'ASC')->pluck('name', 'id');

        return view('hotels.add-sales-data', compact('MasterHotel'));
    }

    public function addSalesRequest(Request $request)
    {
        // echo "<pre>";print_r($request->all());exit;
        $validate = Validator::make($request->all(), [
            // 'hotel_id' => 'required|string',
            // 'rooms' => 'required|string',
            // 'hotel_name' => 'required|string',
            'check_date' => 'required|string',
        ]);
        if ($validate->fails()) {
            $errors = $validate->errors();
            return Redirect::to('add-sales-data')->withErrors($validate)->withInput();
        } else {
            $check_date = explode(' - ', $request->check_date);
            $start_date = date("Y-m-d", strtotime($check_date[0]));
            $end_date = date("Y-m-d", strtotime($check_date[1]));
            $rooms = json_decode($request->rooms, 1);

            $BlockData = HotelSale::whereIn('hotel_id', $request->hotel_id)
                ->where(function ($query) use ($start_date, $end_date) {
                    $query->whereRaw("(start_date <= '". $start_date ."' AND end_date >= '". $end_date ."')");
                    $query->orWhereRaw("(start_date >= '". $start_date ."' AND end_date <= '". $end_date ."')");
                    $query->orWhereBetween('start_date', [$start_date, $end_date]);
                    $query->orWhereBetween('end_date', [$start_date, $end_date]);
                })->get()->toarray();
            if (empty($BlockData)) {
                $vendor_id = (Auth::user()->role == 2) ? Auth::user()->id : Auth::user()->vendor_id;

                foreach ($request->hotel_id as $key => $value) {
                    $MasterHotel = MasterHotel::find($value);
                    $HotelSale[$key] = [
                        'vendor_id' => $vendor_id,
                        'hotel_id' => $value,
                        'hotel_name' => $MasterHotel->name,
                        // 'room_id' => $value,
                        // 'room_name' => $HotelRoom->title,
                        'start_date' => $start_date,
                        'end_date' => $end_date,
                        'created_by' => Auth::user()->id,
                    ];
                }
                $save_status = HotelSale::insert($HotelSale);

                if ($save_status) {
                    Session::flash('success', 'Hotel inventory stopped successfully.');
                    return Redirect::to('hotel-sales');
                } else {
                    Session::flash('success', 'Unable to stop hotel inventory.');
                    return Redirect::to('add-sales-data');
                }
            } else {
                Session::flash('success', "Inventory already stopped in between these date. please change the date and try again!");
                return Redirect::to('add-sales-data');
            }
        }
    }

