    public function createBlockedHotelOrder(Request $request)
    {
        if (!(parent::checkWritePrivilege(29))) {
            Session::flash('success', 'You are not autherised to do this operation.');
            return redirect()->back();
        }
        //        echo "<pre>";print_r($request->all());exit;
        $BookStatus = 1;
        $service = explode('~', $request->service_name_id);
        $check_date = explode(' - ', $request->check_date);
        $chko_date = ($check_date[0] == $check_date[1]) ? date("Y-m-d", strtotime($check_date[1])) : date("Y-m-d", strtotime($check_date[1]  . '-1 days'));
        // $BlockedHotel = BlockedHotel::where('hotel_id', $service[1])
        //     ->whereBetween('block_date', [date("Y-m-d", strtotime($check_date[0])), $chko_date])
        //     ->get()->toArray();
        // if (!empty($BlockedHotel)) {
        //     Session::flash('success', 'The hotel is blocked. Please change date and try again.');
        //     return Redirect::to('offline-order');
        // }
        $state = !empty($request->customer_state) ? explode('~', $request->customer_state) : [];
        $country = !empty($request->customer_country) ? explode('~', $request->customer_country) : [];
        if ($check_date[0] == $check_date[1]) {
            $days = 1;
        } else {
            $difference = strtotime($check_date[1]) - strtotime($check_date[0]);
            $days = round($difference / (60 * 60 * 24));
        }
        $room_details = json_decode($request->room_details, 1);
        $available_rooms = array();
        $BlockedHotel = BlockedHotel::where('hotel_id', $service[1])
            ->whereBetween('block_date', [date("Y-m-d", strtotime($check_date[0])), $chko_date])
            ->pluck('rooms')->toArray();
        $BlockedRooms = array();
        if (!empty($BlockedHotel)) {
            $BlockedRoomsStr = implode(",", $BlockedHotel);
            $BlockedRooms = explode(",", $BlockedRoomsStr);
            $BlockedRooms = array_unique($BlockedRooms);
        }
        for ($i = 0; $i < $days; $i++) {
            $checkDate = date("Y-m-d", strtotime($check_date[0] . ' + ' . $i . ' days'));
            foreach ($room_details as $value) {
                if (!empty($BlockedRooms) && in_array($value['id'], $BlockedRooms)) {
                    $BookStatus = 0;
                }
                $MasterInventory = MasterInventory::where(['date' => $checkDate, 'room_id' => $value['id']])->first();
                $total_available = !empty($MasterInventory) ? $MasterInventory->total_blocked : 0;
                if (array_key_exists($checkDate, $available_rooms) && array_key_exists($value['id'], $available_rooms[$checkDate])) {
                    $available_rooms[$checkDate][$value['id']]['available'] = $total_available;
                    $available_rooms[$checkDate][$value['id']]['request'] += 1;
                } else {
                    $available_rooms[$checkDate] = array($value['id'] => ['available' => $total_available, 'request' => 1]);
                }
            }
        }
        foreach ($available_rooms as $dates) {
            foreach ($dates as $rooms) {
                if ($rooms['available'] < $rooms['request']) {
                    $BookStatus = 0;
                    break 2;
                }
            }
        }
        if ($BookStatus == 0) {
            Session::flash('failure', 'Sorry!, the rooms you have selected not available. Please change date and try again.');
            return Redirect::to('offline-order');
        }

        $vendor_id = (Auth::user()->role == 2) ? Auth::user()->id : Auth::user()->vendor_id;
        $VendorData = User::find($vendor_id);

        $lastIdData = OrderMaster::orderBy('id', 'desc')->first();
        $lastId = !empty($lastIdData) ? $lastIdData->id + 1 : 1;
        $booking_id = 'OT-' . time() . '-' . $vendor_id . '-' . $lastId;


        $MasterHotel = MasterHotel::find($service[1]);

        $userId = null;
        if ((Auth::user()->user_role == 'agent_staff')) {
            $userId = Auth::user()->id;
        } else {
            $UserDetails = User::where('email', $request->customer_email)->orWhere('phone', $request->customer_phone)->first();
            if (!empty($UserDetails)) {
                $userId = $UserDetails->id;
            } else {
                $NewUser = new User([
                    'email' => $request->customer_email,
                    'password' => bcrypt(rand(10000000, 99999999)),
                    'first_name' => $request->customer_name,
                    'phone' => $request->customer_phone,
                    'pincode' => $request->zipcode,
                    'address' => $request->customer_address1,
                    'address2' => $request->address2,
                    'country' => !empty($country) ? $country[1] : null,
                    'state' => !empty($state) ? $state[1] : null,
                    'city' => $request->customer_city,
                    'vendor_id' => 0,
                    'role' => 4,
                    'access_type' => 'customer',
                    'login_type' => 'email',
                    'status' => 1,
                    'create_account_approval' => 0
                ]);
                if ($NewUser->save()) {
                    $userId = $NewUser->id;
                }
            }
        }
        $cart_details = json_decode($request->cart_details, 1);
        $room_data = array();
        $rooms_array = array();
        foreach ($cart_details as $value) {
            $room_data[$value['roomId']] = array('room_name' => $value['roomName'], 'quantity' => count($value['guestData']));
            array_push($rooms_array, $value['roomId']);
        }
        $total_room_category = count($cart_details);
        $room_slug = implode('~', $rooms_array);

        //        $difference = strtotime($check_date[1]) - strtotime($check_date[0]);
        //        $days = round($difference / (60 * 60 * 24));
        $room_details = json_decode($request->room_details, 1);
        $extra_guests = $extra_guest_price = 0;
        foreach ($room_details as $value) {
            $extra_guests += $value['extra_bed'];
            $extra_guest_price += $value['extra_bed'] * $value['extra_bed_price'] * $days;
        }
        $invoice_id = '';
        $LastOrder = OrderMaster::select(DB::raw('count(id) as totOrder'))->where('service_type', 'hotel')->where('status', '!=', 'partially-cancelled')->first();
        if ($LastOrder->totOrder > 0) {
            $LastInvoiceId = (int)$LastOrder->totOrder + 1;
            $invoice_id = date('dmY') . 'H00' . $LastInvoiceId;
        } else {
            $invoice_id = date('dmY') . 'H001';
        }
        $status = (in_array($request->payment_gateway, ['cash', 'credit', 'upi', 'card'])) ? 'completed' : 'pending';
        $payment_status = (in_array($request->payment_gateway, ['cash', 'credit', 'upi', 'card'])) ? 'success' : 'pending';
        $payment_method = (in_array($request->payment_gateway, ['cash', 'credit', 'upi', 'card'])) ? $request->payment_gateway : '';
        $Paytm_Mid = '';
        $split_status = 0;
        if ($request->payment_gateway == 'paytm') {
            $Paytm_Mid = $MasterHotel->paytm_mid;
            $split_status = 1;
        } elseif ($request->payment_gateway == 'hdfc') {
            $Paytm_Mid = $MasterHotel->hdfc_mid;
            $split_status = 0;
        }
        $admin_amount = $vendor_amount = 0;
        if (!empty($vendorData)) {
            $admin_percent = $vendorData->admin_commission;
            if (!empty($Paytm_Mid) && $admin_percent > 0) {
                $vendor_amount = $request->total_order_price - ceil($request->total_order_price * ($admin_percent / 100));
                $admin_amount = $request->total_order_price - $vendor_amount;
            } else {
                $admin_amount = $request->total_order_price;
                $vendor_amount = 0;
            }
        }
        $order_type = (Auth::user()->user_role == 'agent_staff') ? Auth::user()->first_name : 'offline';
        $invoice_serial = '';
        // if ($request->payment_gateway == 'cash') {
        //     if ($vendor_id == 3) {
        //         $LastOrder = OrderMaster::select(DB::raw('count(id) as totOrder'))
        //                     ->where(['service_type' => 'hotel', 'vendor_id' => 3, 'payment_status' => 'success'])
        //                     ->whereRaw("(status = 'cancelled' OR status = 'completed')")
        //                     ->first();
        //         if ($LastOrder->totOrder > 0) {
        //             $LastInvoiceId = (int)$LastOrder->totOrder + 1;
        //             $invoice_serial = $MasterHotel->serial_prefix .'00'. $LastInvoiceId;
        //         } else {
        //             $invoice_serial = $MasterHotel->serial_prefix .'001';
        //         }
        //     }
        // }

        $OrderMaster = new OrderMaster([
            'order_id' => $booking_id,
            'invoice_id' => $invoice_id,
            'invoice_serial' => $invoice_serial,
            'vendor_id' => $vendor_id,
            'vendor_name' => $VendorData->company,
            'order_type' => $order_type,
            'customer_id' => $userId,
            'customer_name' => trim($request->customer_name),
            'customer_email' => trim($request->customer_email),
            'customer_phone' => trim($request->customer_phone),
            'customer_address1' => parent::cleanString(trim($request->customer_address1)),
            'customer_city' => parent::cleanString(trim($request->customer_city)),
            'customer_state' => !empty($state) ? parent::cleanString(trim($state[0])) : '',
            'customer_zipcode' => trim($request->customer_zipcode),
            'gst_regd_no' => trim($request->gst_regd_no),
            'gst_company_name' => trim($request->gst_company_name),
            'gst_company_address' => trim($request->gst_company_address),
            'customer_country' => !empty($country) ? parent::cleanString(trim($country[0])) : '',
            'book_naration' => addslashes(trim($request->book_naration)),
            'service_type' => 'hotel',
            'service_name' => $service[0],
            'service_name_id' => $service[1],
            'service_city' => $request->service_city,
            'start_date' => date("Y-m-d", strtotime($check_date[0])),
            'end_date' => date("Y-m-d", strtotime($check_date[1])),
            'room_request' => $request->room_details,
            'room_details' => json_encode($room_data),
            'room_slug' => $room_slug,
            'start_time' => $MasterHotel->check_in_time,
            'end_time' => $MasterHotel->check_out_time,
            'total_room_category' => $total_room_category,
            'total_rooms' => $request->total_rooms,
            'total_guests' => $request->total_adult + $request->total_child,
            'total_adults' => $request->total_adult,
            'total_child' => $request->total_child,
            'extra_guests' => $extra_guests,
            'extra_person_price' => $extra_guest_price,
            'total_service_price' => $request->total_room_price,
            'sub_total_price' => $request->sub_total_price,
            'coupon_name' => $request->coupon_name,
            'coupon_code' => $request->coupon_code,
            'coupon_amount' => $request->coupon_amount,
            'tax_percentage' => ($request->tax_amount > 0) ? $request->tax_percentage : 0,
            'tax_amount' => $request->tax_amount,
            'service_charge' => $request->service_charge,
            'total_order_price' => $request->total_order_price,
            'status' => $status,
            'payment_gateway' => $request->payment_gateway,
            'payment_method' => $payment_method,
            'payment_status' => $payment_status,
            'split_initiate_status' => $split_status,
            'admin_amount' => $admin_amount,
            'vendor_amount' => $vendor_amount,
            'book_from' => $request->book_from,
            'request_from' => 'web'
        ]);
        //        echo "<pre>";print_r($OrderMaster);exit;
        if ($OrderMaster->save()) {
            $OrderMasterId = $OrderMaster->id;
            $OrderMasterNew = OrderMaster::find($OrderMasterId);
            $OrderDetailsData = array();
            $count = 0;
            $room_no = 1;

            if (in_array($request->payment_gateway, ['cash', 'credit', 'upi', 'card'])) {
                // Generate Qr Code
                require_once public_path('QrCode/generateQrCode.php');
                $QrCodeData = array(
                    'invoiceId' => $OrderMasterNew->invoice_id,
                    'orderId' => $OrderMasterNew->order_id,
                    'txnId' => $OrderMasterNew->transaction_id,
                    'serviceType' => $OrderMasterNew->service_type,
                );
                $QrCode = generateQrCode(json_encode($QrCodeData));
                $OrderMasterNew->qr_code = $QrCode;
                $OrderMasterNew->qr_verified = 0;
                $invoice_serial = '';
                if (date("Y-m-d", strtotime($OrderMasterNew->created_at)) >= "2023-04-01" && $OrderMasterNew->vendor_id == 1) {
                // if ($OrderMasterNew->vendor_id == 3) {
                    // $LastOrder = OrderMaster::select(DB::raw('count(id) as totOrder'))
                    //             ->where(['service_type' => 'hotel', 'vendor_id' => 3, 'payment_status' => 'success'])
                    //             ->where('status', '!=', 'partially-cancelled')
                    //             ->where('order_type', '!=', 'online')
                    //             ->first();
                    // if ($LastOrder->totOrder > 0) {
                    //     $LastInvoiceId = (int)$LastOrder->totOrder;
                    //     $invoice_serial = 'C00'. $LastInvoiceId;
                    // } else {
                    //     $invoice_serial = 'C001';
                    // }
                    $LastOrder = OrderMaster::select(DB::raw('count(id) as totOrder'))
                                ->where(['service_type' => 'hotel', 'service_name_id' => $OrderMasterNew->service_name_id, 'payment_status' => 'success'])
                                ->where('status', '!=', 'partially-cancelled')
                                ->where('created_at', '>=', date("Y-m-d", strtotime("2023-04-01")))
                                ->first();
                    if ($LastOrder->totOrder > 0) {
                        $LastInvoiceId = (int)$LastOrder->totOrder;
                        $invoice_serial = $MasterHotel->serial_prefix .'0'. $LastInvoiceId;
                    } else {
                        $invoice_serial = $MasterHotel->serial_prefix .'01';
                    }
                    OrderMaster::find($OrderMasterNew->id)->update(['invoice_serial' => $invoice_serial]);
                    $OrderMasterNew->invoice_serial = $invoice_serial;
                } elseif ($OrderMasterNew->vendor_id == 3) {
                    $LastOrder = OrderMaster::select(DB::raw('count(id) as totOrder'))
                                ->where(['service_type' => 'hotel', 'service_name_id' => $OrderMasterNew->service_name_id, 'payment_status' => 'success'])
                                ->where('status', '!=', 'partially-cancelled')
                                ->where('created_at', '>=', date("Y-m-d", strtotime("2023-09-14")))
                                ->first();
                    if ($LastOrder->totOrder > 0) {
                        $LastInvoiceId = (int)$LastOrder->totOrder;
                        $invoice_serial = $MasterHotel->serial_prefix .'0'. $LastInvoiceId;
                    } else {
                        $invoice_serial = $MasterHotel->serial_prefix .'01';
                    }
                    OrderMaster::find($OrderMasterNew->id)->update(['invoice_serial' => $invoice_serial]);
                    $OrderMasterNew->invoice_serial = $invoice_serial;
                }
            }

            $Pricing_data = json_decode($request->pricing_details, 1);
            $OrderLogData = array();
            //            $GSTData = GstDetail::select(DB::raw('sum(value) AS totTaxPercent'))->first();
            if ($MasterHotel->gst_applicable == 1) {
                $GstTable = GstTable::where(['vendor_id' => $MasterHotel->vender_id, 'service_type' => 'hotel'])
                    ->orderBy('min_amount', 'asc')
                    ->pluck('gst', 'min_amount')->toArray();
                $GstDetails = array();
                if (!empty($GstTable)) {
                    foreach ($GstTable as $k => $gst) {
                        $GstDetails[$k] = json_decode($gst, 1);
                    }
                } else {
                    $GstDetails[0] = $GSTData;
                }
                $GstMin = array_keys($GstDetails);
            }
            $GstShowData = $tax_array = array();
            $total_gst = $total_coupon_amt = $SubTotal = 0;

            require_once public_path('paytm_lib/config_paytm.php');
            if ($request->payment_gateway == 'hdfc') {
                $PropertyAccount = PropertyAccount::where(['service_type' => $OrderMasterNew->service_type, 'service_id' => $OrderMasterNew->service_name_id])->first();
                if (!empty($PropertyAccount) && PAYTM_ENVIRONMENT == 'PROD') {
                    $HDFC_KEY = $PropertyAccount->hdfc_key;
                    $HDFC_SALT = $PropertyAccount->hdfc_salt;
                    $MERCHANT_ID = $PropertyAccount->hdfc_mid;
                }
