    public function createHotelEstimateRequest(Request $request)
    {
        if (!(parent::checkWritePrivilege(96))) {
            Session::flash('success', 'You are not autherised to do this operation.');
            return redirect()->back();
        }
        // echo "<pre>";print_r($request->all());exit;
        $BookStatus = 1;
        $service = explode('~', $request->service_name_id);
        $check_date = explode(' - ', $request->check_date);
        $start_date =  $check_date[0];
        $end_date =  $check_date[1];

        $state = !empty($request->customer_state) ? explode('~', $request->customer_state) : [];
        $country = !empty($request->customer_country) ? explode('~', $request->customer_country) : [];
        if ($check_date[0] == $check_date[1]) {
            $days = 1;
        } else {
            $difference = strtotime($check_date[1]) - strtotime($check_date[0]);
            $days = round($difference / (60 * 60 * 24));
        }
        $room_details = json_decode($request->room_details, 1);

        $vendor_id = (Auth::user()->role == 2) ? Auth::user()->id : Auth::user()->vendor_id;
        $Vendor = User::find($vendor_id);

        $MasterHotel = MasterHotel::find($service[1]);

        $cart_details = json_decode($request->cart_details, 1);
        $room_data = array();
        $rooms_array = array();
        foreach ($cart_details as $value) {
            $room_data[$value['roomId']] = array('room_name' => $value['roomName'], 'quantity' => count($value['guestData']));
            array_push($rooms_array, $value['roomId']);
        }
        $total_room_category = count($cart_details);
        $room_slug = implode('~', $rooms_array);

        $room_details = json_decode($request->room_details, 1);
        $extra_guests = $extra_guest_price = 0;
        foreach ($room_details as $value) {
            $extra_guests += ($value['extra_bed'] * $value['quantity']);
            $extra_guest_price += ($value['extra_bed'] * $value['extra_bed_price'] * $days * $value['quantity']);
        }
        $invoice_id = '';
        $LastOrder = HotelEstimate::select(DB::raw('count(id) as totOrder'))->where('service_type', 'hotel')->where('service_category', 'room')->first();
        if ($LastOrder->totOrder > 0) {
            $LastInvoiceId = (int)$LastOrder->totOrder + 1;
            $invoice_id = date('dmy') . 'EB0' . $LastInvoiceId;
        } else {
            $invoice_id = date('dmy') . 'EB01';
        }
        $est_type = ($request->est_type == 'estimate') ? 'Estimate' : 'Bill';

        $HotelInvoice = EmailTemplate::where('ref_code', 'hotelInvoice')->first();
        $Message = '';
        if (!empty($HotelInvoice)) {
            $check_date = date("d M Y", strtotime($check_date[0])) . ' - ' . date("d M Y", strtotime($check_date[1]));
            $Coupon_percent = $sgst = $cgst = 0;
            $totalNight = $days;
            $hotelGSTNo = (!empty($MasterHotel->gst_number)) ? $MasterHotel->gst_number : 'N/A';
            $hotelRegdCompany = (!empty($MasterHotel->gst_legal_name)) ? $MasterHotel->gst_legal_name : 'N/A';
            $customerGSTNo = !empty($request->gst_regd_no) ? '<u><b>GSTN No: '. $request->gst_regd_no .'</b></u>' : '';
            $customerGSTCompany = !empty($request->gst_regd_no) ? '<u><b>Company Name: '. $request->gst_company_name .'</b></u>' : '';

            $room_pricing = '';
            foreach ($room_details as $value) {
                $roomQty = $value['quantity'];
                $rate = ($value['price'] / $totalNight) - ($value['extra_bed'] * $value['extra_bed_price']);
                $roomPrice = $rate * $roomQty * $totalNight;
                $extraPerson = $value['extra_bed'];
                $extraPrice = $value['extra_bed_price'] * $value['extra_bed'] * $totalNight * $roomQty;

                $room_pricing .= '<tr><td align="center" valign="middle" style="color:#000;border-right:1px solid #000; border-bottom:1px solid #000">' . $invoice_id . '</td><td align="center" valign="middle" style="color:#000;border-right:1px solid #000; border-bottom:1px solid #000">' . $service[0] . '</td><td align="center" valign="middle" style="color:#000;border-right:1px solid #000; border-bottom:1px solid #000">' . $value['name'] . '</td><td align="center" valign="middle" style="color:#000;border-right:1px solid #000; border-bottom:1px solid #000">' . $check_date . '</td><td align="center" valign="middle" style="color:#000;border-right:1px solid #000; border-bottom:1px solid #000">' . $roomQty . '</td><td align="center" valign="middle" style="color:#000;border-right:1px solid #000; border-bottom:1px solid #000">' . number_format($rate, 2) . '</td><td align="center" valign="middle" style="color:#000;border-right:1px solid #000; border-bottom:1px solid #000">' . number_format($roomPrice, 2) . '</td></tr>';
                if ($extraPerson > 0) {
                    $room_pricing .= '<tr><td align="center" valign="middle" colspan="2" style="color:#000;border-right:1px solid #000; border-bottom:1px solid #000"></td><td align="center" valign="middle" style="color:#000;border-right:1px solid #000; border-bottom:1px solid #000">Extra Person (' . $extraPerson . ')</td><td align="center" valign="middle" style="color:#000;border-right:1px solid #000; border-bottom:1px solid #000">' . $check_date . '</td><td align="center" valign="middle" style="color:#000;border-right:1px solid #000; border-bottom:1px solid #000"></td><td align="center" valign="middle" style="color:#000;border-right:1px solid #000; border-bottom:1px solid #000">' . number_format($value['extra_bed_price'], 2) . '</td><td align="center" valign="middle" style="color:#000;border-right:1px solid #000; border-bottom:1px solid #000">' . number_format($extraPrice, 2) . '</td></tr>';
                }
            }
            $discount = (!empty($request->coupon_amount && $request->coupon_amount > 0)) ? number_format($request->coupon_amount, 2) : '0.00';
            $tspinword = parent::AmountInWords($request->total_room_price);
            $customer_address = $request->customer_address1;
            $customer_address .= !empty($request->customer_city) ? ',<br>'. $request->customer_city : '';
            $customer_address .= !empty($state) ? ',<br>'. trim($state[0]) : '';
            $customer_address .= !empty($country) ? ',<br>'. $country[0] : '';
            $customer_address .= !empty($request->customer_zipcode) ? ', '. $request->customer_zipcode : '';

            $Message = str_replace(
                array("~otdcLogo~", "~username~", "~usermobile~", "~usermail~", "~useraddress~", "~usergstno~", "~usergstcompany~", "~hoteladdress~", "~hotelemail~", "~hotelgst~", "~hotelgstcompany~", "~vendorLogo~", "~orderdate~", "~roomfeesdetails~", "~totalserviceprice~", "~couponamount~", "~subtotal~", "~gst~", "~ordertotal~", "~paymentmethod~", "~txnid~", "~couponname~", "~tspinword~", "~payuid~"),
                array($this->site, $request->customer_name, $request->customer_phone, $request->customer_email, $customer_address, $customerGSTNo, $customerGSTCompany, $MasterHotel->real_address, $MasterHotel->contact_email, $hotelGSTNo, $hotelRegdCompany, $this->site . $Vendor->photo, date("d M Y h:i a"), $room_pricing, number_format($request->total_room_price, 2), $discount, number_format($request->sub_total_price, 2), number_format($request->tax_amount, 2), number_format($request->total_order_price, 2), '', '', '', $tspinword, ''),
                $HotelInvoice->source
            );
