    public function getHotelInventory(Request $request)
    {

        $aColumns = array('room_id', 'initial_quantity', 'total_available', 'total_booked', 'total_blocked', 'total_online_completed', 'total_online_pending', 'total_offline_completed', 'total_offline_pending', 'total_tour_booking', 'id');
        $sIndexColumn = "id";
        $sTable = "master_inventory";
        /*
         * Paging
         */
        $sLimit = "";
        if (isset($_POST['start']) && $_POST['length'] != '-1') {
            $sLimit = "LIMIT " . intval($_POST['start']) . ", " . intval($_POST['length']);
        }
        /*
         * Ordering
         */
        $sOrder = " ORDER BY id DESC ";
        if (isset($_POST['order'])) {
            $sOrder = "ORDER BY ";
            for ($i = 0; $i < intval(count($_POST['order'])); $i++) {
                if ($_POST['columns'][$_POST['order'][$i]['column']]['orderable'] == "true") {
                    $sOrder .= "`" . $aColumns[intval($_POST['order'][$i]['column'])] . "` " .
                        ($_POST['order'][$i]['dir'] === 'asc' ? 'asc' : 'desc') . ", ";
                }
            }
            $sOrder = substr_replace($sOrder, "", -2);
            if ($sOrder == "ORDER BY") {
                $sOrder = "";
            }
        }
        /*
         * Filtering
         * NOTE this does not match the built-in DataTables filtering which does it
         * word by word on any field. It's possible to do here, but concerned about efficiency
         * on very large tables, and MySQL's regex functionality is very limited
         */
        $vender_id = (Auth::user()->role == 2) ? Auth::user()->id : Auth::user()->vendor_id;
        $sWhere = 'WHERE `vendor_id` = ' . $vender_id;
        if (!empty($_POST['searchValue1']) || !empty($_POST['searchValue2'])) {
            $condition1 = '';
            $condition2 = '';
            if (!empty($_POST['searchValue1'])) {
                $_POST['searchValue1'] = parent::cleanString($_POST['searchValue1']);
                $condition1 .= ' AND hotel_id = "' . $_POST['searchValue1'] . '"';
            }
            if (!empty($_POST['searchValue2'])) {
                $condition2 .= ' AND date LIKE "' . date("Y-m-d", strtotime($_POST['searchValue2'])) . '"';
            }
            $sWhere .= $condition1 . $condition2;
        }
        if (isset($_POST['search']['value']) && $_POST['search']['value'] != "") {
            $sWhere .= " AND (";
            for ($i = 0; $i < count($aColumns); $i++) {
                $sWhere .= "`" . $aColumns[$i] . "` LIKE '%" . $_POST['search']['value'] . "%' OR ";
            }
            $sWhere = substr_replace($sWhere, "", -3);
            $sWhere .= ')';
        }

        /* Individual column filtering */
        for ($i = 0; $i < count($aColumns); $i++) {
            if (isset($_POST['bSearchable_' . $i]) && $_POST['bSearchable_' . $i] == "true" && $_POST['sSearch_' . $i] != '') {
                if ($sWhere == "") {
                    $sWhere = "WHERE ";
                } else {
                    $sWhere .= " AND ";
                }
                $sWhere .= "`" . $aColumns[$i] . "` LIKE '%" . $_POST['sSearch_' . $i] . "%' ";
            }
        }

        /*
         * SQL queries
         * Get data to display
         */
        $sQuery = "SELECT SQL_CALC_FOUND_ROWS * FROM   $sTable $sWhere $sOrder $sLimit";
        //        echo $sQuery;exit;
        $rResult = DB::select($sQuery);

        /* Data set length after filtering */
        $sQuery = "SELECT FOUND_ROWS() as totalrow";
        $aResultFilterTotal = DB::select($sQuery);
        $iFilteredTotal = $aResultFilterTotal[0]->totalrow;
        /* Total data set length */
        $sQuery = "SELECT COUNT(`" . $sIndexColumn . "`) as countindex FROM $sTable $sWhere";
        $aResultTotal = DB::select($sQuery);
        $iTotal = $aResultTotal[0]->countindex;

        /*
         * Output
         */
        $output = array(
            "draw" => intval($_POST['draw']),
            "recordsTotal" => $iTotal,
            "recordsFiltered" => $iFilteredTotal,
            "data" => array()
        );
        $tot_available = $tot_booked = $tot_blocked = $tot_online_completed = $tot_online_pending = $tot_offline_completed = $tot_offline_pending = $tot_tour_booking = 0;
        foreach ($rResult as $aRow) {
            $row = array();
            $RoomDetails = HotelRoom::where(['id' => $aRow->room_id, 'status' => 'publish'])->first();
            if (empty($RoomDetails)) {
                continue;
            }

            $row[] = $RoomDetails->title;
            $row[] = $aRow->initial_quantity;
            $row[] = $aRow->total_available;
            $row[] = ($aRow->total_booked > 0) ? '<a href="' . url('hotel-orders?roomId=' . $RoomDetails->id . '&date=' . $_POST['searchValue2']) . '" target="_blank">' . $aRow->total_booked . '</a>' : $aRow->total_booked;
            $row[] = $aRow->total_blocked;
            $row[] = $aRow->total_online_completed;   //($aRow->total_online_completed > 0) ? '<a href="javascript:void(0)" class="total-booking" data-id="' . $RoomDetails->id . '">' . $aRow->total_online_completed . '</a>' :
            $row[] = $aRow->total_online_pending;     //($aRow->total_online_pending > 0) ? '<a href="javascript:void(0)" class="total-booking" data-id="' . $RoomDetails->id . '">' . $aRow->total_online_pending . '</a>' :
            $row[] = $aRow->total_offline_completed;  //($aRow->total_offline_completed > 0) ? '<a href="javascript:void(0)" class="total-booking" data-id="' . $RoomDetails->id . '">' . $aRow->total_offline_completed . '</a>' :
            $row[] = $aRow->total_offline_pending;    //($aRow->total_offline_pending > 0) ? '<a href="javascript:void(0)" class="total-booking" data-id="' . $RoomDetails->id . '">' . $aRow->total_offline_pending . '</a>' :
            $row[] = $aRow->total_tour_booking;

            $output['data'][] = $row;

            $tot_available += $aRow->total_available;
            $tot_booked += $aRow->total_booked;
            $tot_blocked += $aRow->total_blocked;
            $tot_online_completed += $aRow->total_online_completed;
            $tot_online_pending += $aRow->total_online_pending;
            $tot_offline_completed += $aRow->total_offline_completed;
            $tot_offline_pending += $aRow->total_offline_pending;
            $tot_tour_booking += $aRow->total_tour_booking;
        }
        $output['total'] = [
            'tot_available' => $tot_available,
            'tot_booked' => $tot_booked,
            'tot_blocked' => $tot_blocked,
            'tot_online_completed' => $tot_online_completed,
            'tot_online_pending' => $tot_online_pending,
            'tot_offline_completed' => $tot_offline_completed,
            'tot_offline_pending' => $tot_offline_pending,
            'tot_tour_booking' => $tot_tour_booking
        ];
        echo json_encode($output);
        exit;
    }

