                $HotelInvoice = EmailTemplate::where('ref_code', 'hotelInvoice')->first();
                $Subject = $Message = '';
                if (!empty($HotelInvoice)) {
                    $Subject = 'Booking Shifting - ' . $OrderMasterNew['service_name'] . ' - Booking ID - ' . $OrderMasterNew['invoice_id'];
                    $room_html = '';
                    $room_details = json_decode($OrderMasterNew['room_details'], 1);
                    foreach ($room_details as $value) {
                        $room_html .= $value['quantity'] . ' x ' . $value['room_name'] . ', ';
                    }
