    public function modifyInventoryRequest(Request $request)
    {
        $validate = Validator::make($request->all(), [
            'hotel_id' => 'required|numeric',
            'room_id' => 'required|numeric',
            'block_date' => 'required|string',
            'operation' =>  'required|string',
            'quantity' => 'required|numeric|min:1'
        ]);
        if ($validate->fails()) {
            $errors = $validate->errors();
            return Redirect::to('modify-hotel-inventory')->withErrors($validate)->withInput();
        } else {
            $block_date = explode(" - ", $request->block_date);
            $start_date = date("Y-m-d", strtotime($block_date['0']));
            $end_date = date("Y-m-d", strtotime($block_date['1']));
            $OrderData = MasterInventory::where('room_id', $request->room_id)
                ->whereBetween('date', [$start_date, $end_date])
                ->get();
            if (!empty($OrderData)) {
                $MasterHotel = MasterHotel::find($request->hotel_id);
                if (!empty($MasterHotel)) {
                    $HotelRoom = HotelRoom::find($request->room_id);
                    $status = 0;
                    foreach ($OrderData as $value) {
                        $MasterInventory = MasterInventory::where(['room_id' => $request->room_id, 'date' => $value->date])->first();
                        if (!empty($MasterInventory)) {
                            if ($request->operation == 'increase') {
                                $MasterInventory->total_available += $request->quantity;
                                $MasterInventory->initial_quantity += $request->quantity;
                            } elseif ($request->operation == 'decrease') {
                                $block_qty = ($MasterInventory->total_available >= $request->quantity) ? $request->quantity : $MasterInventory->total_available;
                                $MasterInventory->initial_quantity -= $block_qty;
                                $MasterInventory->total_available -= $block_qty;
                            }
                            if ($MasterInventory->save()) {
                                $status = 1;
                                $FullBlockData = BlockedHotel::where(['hotel_id' => $MasterHotel->id, 'block_date' => $MasterInventory->date])
                                                ->whereRaw("find_in_set('". $HotelRoom->id ."',rooms)")
                                                ->first();
                                if (!empty($MasterHotel->mmt_hotel_id) && !empty($HotelRoom->mmt_room_id)) {

                                    $BlockedMmt = BlockedMmtInventory::where('hotel_id', $MasterHotel->id)
                                            ->where('block_date', $MasterInventory->date)
                                            ->where('rooms', $MasterInventory->room_id)
                                            ->whereRaw("(platform LIKE 'all' OR platform LIKE 'mmt')")
                                            ->get()->toArray();
                                    $closed = 'false';
                                    if (!empty($FullBlockData) || !empty($BlockedMmt)) {
                                        $closed = "true";
                                    }
                                    $Xml = '<?xml version="1.0" encoding="UTF-8" ?>
                                                <AvailRateUpdateRQ hotelCode="'. $MasterHotel->mmt_hotel_id .'" timeStamp="'. time() .'">
                                                    <AvailRateUpdate locatorID="1">
                                                        <DateRange from="'. $value->date . '" to="' . $value->date .'"/>
                                                        <Availability code="'. $HotelRoom->mmt_room_id .'" count="'. $MasterInventory->total_available .'" closed="'. $closed .'" />
                                                    </AvailRateUpdate>
                                                </AvailRateUpdateRQ>';
                                    DB::insert("INSERT INTO `mmt_availability_logs`(`request_source`, `vendor_id`, `hotel_id`, `hotel_code`, `room_id`, `room_code`, `request_data`, `status`, `created_at`, `request_type`, `quantity`, `date`) VALUES ('manage_inventory', '". $MasterHotel->vender_id ."', '". $MasterHotel->id ."', '". $MasterHotel->mmt_hotel_id ."', '". $HotelRoom->id ."', '". $HotelRoom->mmt_room_id . "', '". $Xml ."', '0', '". date('Y-m-d H:i:s') ."', 'inventory', '". $MasterInventory->total_available ."', '". $MasterInventory->date ."')");
                                }
                                if (!empty($MasterHotel->ctp_hotel_id) && !empty($HotelRoom->ctp_room_id)) {
                                    $closed = "Open";
                                    $BlockedMmt = BlockedMmtInventory::where('hotel_id', $MasterHotel->id)
                                                    ->where('block_date', $MasterInventory->date)
                                                    ->where('rooms', $MasterInventory->room_id)
                                                    ->whereRaw("(platform LIKE 'all' OR platform LIKE 'cleartrip')")
                                                    ->get()->toArray();
                                    if (!empty($FullBlockData) || !empty($BlockedMmt)) {
                                        $closed = "Close";
                                    }
                                    $InvRateplanData = CtpRatePlans::where(['room_type_code' => $HotelRoom->ctp_room_id])->first();
                                    if (!empty($InvRateplanData)) {
                                        // Availability
                                        $Xml = '<OTA_HotelAvailNotifRQ xmlns="http://www.opentravel.org/OTA/2003/05" Version="1.0" EchoToken="1234">
                                                    <AvailStatusMessages HotelCode="'. $MasterHotel->ctp_hotel_id .'">
                                                        <AvailStatusMessage BookingLimit="'. $MasterInventory->total_available .'">
                                                            <StatusApplicationControl Start="'. $value->date .'" End="'. $value->date .'" InvTypeCode="'. $HotelRoom->ctp_room_id .'" RatePlanCode="'. $InvRateplanData->rate_plan_code .'" />
                                                            <RestrictionStatus Status="'. $closed .'" />
                                                        </AvailStatusMessage>
                                                    </AvailStatusMessages>
                                                </OTA_HotelAvailNotifRQ>';
                                        DB::insert("INSERT INTO `ctp_availability_logs`(`request_source`, `vendor_id`, `hotel_id`, `hotel_code`, `room_id`, `room_code`, `request_data`, `status`, `created_at`, `request_type`, `quantity`, `date`) VALUES ('manage_inventory', '". $MasterHotel->vender_id ."', '". $MasterHotel->id ."', '". $MasterHotel->ctp_hotel_id ."', '". $HotelRoom->id ."', '". $HotelRoom->ctp_room_id . "', '". $Xml ."', '0', '". date('Y-m-d H:i:s') ."', 'inventory', '". $MasterInventory->total_available ."', '". $MasterInventory->date ."')");
                                    }
                                }
                            }
                        }
                    }
                    if ($status == 1) {
                        Session::flash('success', 'Hotel inventory updated successfully.');
                        return Redirect::to('manage-hotel-inventory');
                    } else {
                        Session::flash('success', 'Unable to block room. please try again.');
                        return Redirect::to('modify-hotel-inventory');
                    }
                } else {
                    Session::flash('success', 'Unable to block room. please try again.');
                    return Redirect::to('modify-hotel-inventory');
                }
            } else {
                Session::flash('success', 'Unable to block room.');
                return Redirect::to('modify-hotel-inventory');
            }
        }
    }

    public function hotelMisReport()
    {
        if (!(parent::checkViewPrivilege(71))) {
            Session::flash('success', 'You are not autherised to view this page.');
            return redirect()->back();
        }
        $vender_id = 0;
        $MasterHotelQuery = DB::table("master_hotels"); // MasterHotel::where('status', 'publish');
        if (Auth::user()->access_type == 'vendor') {
            $vender_id = (Auth::user()->role == 2) ? Auth::user()->id : Auth::user()->vendor_id;
            $MasterHotelQuery->where('vender_id', $vender_id);
            if ((Auth::user()->role == 3)) {
                $SubuserAccess = SubuserAccess::where(['user_id' => Auth::user()->id, 'service' => 'hotel'])->pluck('service_id', 'id')->toArray();
                if (!empty($SubuserAccess)) {
                    $MasterHotelQuery->whereIn('id', array_values($SubuserAccess));
                }
            }
        }
        $MasterHotel = $MasterHotelQuery->orderBy('id', 'ASC')->pluck('name', 'id')->toArray();
        $hotelIds = array_keys($MasterHotel);

        $start_date = date("Y-m-d");
        if ($vender_id == 3) { $start_date = $this->ecoInventoryDate; }
        $end_date = date('Y-m-d', strtotime($start_date . ' +120 days'));
        if (isset($_GET['check_date'])) {
            $check_date = explode(' - ', $_GET['check_date']);
            $start_date = date("Y-m-d", strtotime($check_date[0]));
            $end_date = date("Y-m-d", strtotime($check_date[1]));
        }
        $MisData = array();
        $AllAvailable = $AllBooked = 0;
        foreach ($MasterHotel as $key => $value) {
            $HotelRoom = HotelRoom::select(DB::raw('SUM(quantity) AS totRoom'))->where(['hotel_id' => $key, 'status' => 'publish'])->first();
            if (!empty($HotelRoom->totRoom)) {
                $MisData['hotels'][$value] = $HotelRoom->totRoom;
            } else {
                $MisData['hotels'][$value] = 0;
            }

            $MasterInventory = MasterInventory::select('date', DB::raw('SUM(total_booked) as totalBook'))
                ->where('hotel_id', $key)
                ->whereBetween('date', [date("Y-m-d", strtotime($start_date)), date("Y-m-d", strtotime($end_date))])
                ->groupBy('date')
                ->pluck('totalBook', 'date');
            foreach ($MasterInventory as $dates => $qty) {
                if (empty($MisData['data'][$dates])) {
                    foreach ($hotelIds as $hids) {
                        $MisData['data'][$dates][$hids] = 0;
                    }
                }
                $MisData['data'][$dates][$key] = $qty;
            }
            if (!isset($MisData['data'])) {
                $MisData['data'] = [];
            }
            ksort($MisData['data']);
            $TotalInventory = MasterInventory::select(DB::raw('SUM(total_booked) as totalBook'), DB::raw('SUM(initial_quantity) as totalAvailable'))
                ->where('hotel_id', $key)
                ->whereBetween('date', [date("Y-m-d", strtotime($start_date)), date("Y-m-d", strtotime($end_date))])
                ->first();
            if (!empty($TotalInventory)) {
                $MisData['totBooked'][$key] = !is_null($TotalInventory->totalBook) ? $TotalInventory->totalBook : 0;
                $MisData['totAvailable'][$key] = !is_null($TotalInventory->totalAvailable) ? $TotalInventory->totalAvailable : 0;
                $MisData['occupancy'][$key] = ($TotalInventory->totalBook != 0 && $TotalInventory->totalAvailable != 0) ? round(($TotalInventory->totalBook / $TotalInventory->totalAvailable) * 100, 2) : 0;
            } else {
                $MisData['totBooked'][$key] = 0;
                $MisData['totAvailable'][$key] = 0;
                $MisData['occupancy'][$key] = 0;
            }
            $AllAvailable += $MisData['totAvailable'][$key];
            $AllBooked += $MisData['totBooked'][$key];

        }
        $GrandOccPercent = ($AllAvailable != 0 && $AllBooked != 0) ? round(($AllBooked / $AllAvailable) * 100, 2) : 0;
        $MisData['grandBooked'] = $AllBooked;
        $MisData['grandOcc'] = $GrandOccPercent;
        // echo "<pre>";print_r($MisData);exit;
        return view('hotels.hotel-mis-report', compact('MisData', 'MasterHotel', 'start_date', 'end_date'));
    }

    public function hotelRoomNightReport()
    {
        if (!(parent::checkViewPrivilege(94))) {
            Session::flash('success', 'You are not autherised to view this page.');
            return redirect()->back();
        }
        $vender_id = 0;
        $MasterHotelQuery = DB::table("master_hotels"); // MasterHotel::where('status', 'publish');
        if (Auth::user()->access_type == 'vendor') {
            $vender_id = (Auth::user()->role == 2) ? Auth::user()->id : Auth::user()->vendor_id;
            $MasterHotelQuery->where('vender_id', $vender_id);
            if ((Auth::user()->role == 3)) {
                $SubuserAccess = SubuserAccess::where(['user_id' => Auth::user()->id, 'service' => 'hotel'])->pluck('service_id', 'id')->toArray();
                if (!empty($SubuserAccess)) {
                    $MasterHotelQuery->whereIn('id', array_values($SubuserAccess));
                }
            }
        }
        $MasterHotel = $MasterHotelQuery->orderBy('id', 'ASC')->pluck('name', 'id')->toArray();

        $start_date = date("Y-m-d", strtotime('- 30 Days'));
        if ($vender_id == 3) {
            $start_date = $this->ecoStartDate;
        }
        $end_date = date("Y-m-d");
        if (isset($_GET['check_date'])) {
            $check_date = explode(' - ', $_GET['check_date']);
            $start_date = date("Y-m-d", strtotime($check_date[0]));
            $end_date = date("Y-m-d", strtotime($check_date[1]));
        }
        $difference = strtotime($end_date) - strtotime($start_date);
        $days = ($start_date == $end_date) ? 1 : round($difference / (60 * 60 * 24));

        $MisData = array();
        $AllAvailable = $AllBooked = 0;
        foreach ($MasterHotel as $key => $value) {
            for($i = 0; $i <= $days; $i++) {
                $checkDate = date("Y-m-d", strtotime($start_date .' + '. $i .' days'));
                $OrderMaster = OrderMaster::select(DB::raw("SUM(DATEDIFF(end_date, start_date) * total_rooms)as totBook"))
                            ->where(['service_name_id' => $key, 'service_type' => 'hotel', 'status' => 'completed', 'payment_status' => 'success'])
                            ->where('created_at', 'like', $checkDate .'%')
                            // ->groupBy(DB::raw("DATE_FORMAT(created_at, '%Y-%M-%d')"))
                            ->first();
                $MisData['data'][$checkDate][$key] = 0;
                if (!empty($OrderMaster)) {
                    $MisData['data'][$checkDate][$key] = $OrderMaster->totBook;
                }
                $MmtOrderMaster = DB::table("mmt_order_masters")->select(DB::raw("SUM(NumberOfNights * total_rooms)as totBook"))
                            ->where(['service_name_id' => $key, 'status' => 'confirmed'])
                            ->where('booking_date', 'like', $checkDate .'%')
                            ->first();

                if (!empty($MmtOrderMaster)) {
                    $MisData['data'][$checkDate][$key] += $MmtOrderMaster->totBook;
                }
            }
            $totalBook = 0;
            $totalOrderMaster = OrderMaster::select(DB::raw("SUM(DATEDIFF(end_date, start_date) * total_rooms)as totBook"))
                        ->where(['service_name_id' => $key, 'service_type' => 'hotel', 'status' => 'completed', 'payment_status' => 'success'])
                        ->whereBetween('created_at', [$start_date .' 00:00:00', $end_date .' 23:59:59'])
                        ->first();
            if (!empty($totalOrderMaster->totBook)) {
                $totalBook = $totalOrderMaster->totBook;
            }

            $totalMmtOrder = DB::table("mmt_order_masters")->select(DB::raw("SUM(NumberOfNights * total_rooms)as totBook"))
                        ->where(['service_name_id' => $key, 'status' => 'confirmed'])
                        ->whereBetween('booking_date', [$start_date .' 00:00:00', $end_date .' 23:59:59'])
                        ->first();
            if (!empty($totalMmtOrder->totBook)) {
                $totalBook += $totalMmtOrder->totBook;
            }
            $MisData['total'][$key] = $totalBook;
            $MisData['hotels'][] = $value;
        }
        $MisData['grandTotal'] = array_sum(array_values($MisData['total']));
        // echo "<pre>";print_r($MisData);exit;
        return view('hotels.hotel-room-night-report', compact('MisData', 'MasterHotel', 'start_date', 'end_date'));
    }

