            $MasterHotelQuery->where('vender_id', $vender_id);
            if ((Auth::user()->role == 3)) {
                $SubuserAccess = SubuserAccess::where(['user_id' => Auth::user()->id, 'service' => 'hotel'])->pluck('service_id', 'id')->toArray();
                if (!empty($SubuserAccess)) {
                    $MasterHotelQuery->whereIn('id', array_values($SubuserAccess));
                }
            }
        }
        $MasterHotel = $MasterHotelQuery->orderBy('id', 'ASC')->pluck('name', 'id')->toArray();

        $start_date = date("Y-m-d");
        $end_date = date("Y-m-d", strtotime('+ 30 Days'));
        if (isset($_GET['check_date'])) {
            $check_date = explode(' - ', $_GET['check_date']);
            $start_date = date("Y-m-d", strtotime($check_date[0]));
            $end_date = date("Y-m-d", strtotime($check_date[1]));
        }
        $difference = strtotime($end_date) - strtotime($start_date);
        $days = ($start_date == $end_date) ? 1 : round($difference / (60 * 60 * 24));

        $MisData = array();
        $totalData = array_map(function ($val) {
            return ['totalTents' => 0, 'totalPax' => 0];
        }, $MasterHotel);
        $totalTent = $totalPax = 0;$PaxData = array();
        for($i = 0; $i <= $days; $i++) {
            $pax = $tents = 0;
            $checkDate = date("Y-m-d", strtotime($start_date .' + '. $i .' days'));
            $mData = array_map(function ($val) {
                return ['tents' => 0, 'pax' => 0];
            }, $MasterHotel);

            $OrderMaster = OrderMaster::where(['service_type' => 'hotel', 'status' => 'completed', 'payment_status' => 'success'])
                        ->whereIn('service_name_id', array_keys($MasterHotel))
                        ->where('start_date', '<=', $checkDate)
                        ->where('end_date', '>', $checkDate)
                        ->orderBy('service_name_id')
                        ->get();
            if (!empty($OrderMaster)) {
                foreach ($OrderMaster as $val) {
                    $room_request = json_decode($val->room_request, 1);
                    $pax = $tents = 0;
                    foreach ($room_request as $roomno) {
                        $HotelRoom = HotelRoom::find($roomno['id']);
                        if ($roomno['child'] > 0) {
                            if ($roomno['child'] < $HotelRoom->children) {
                                $pax += $roomno['adult'];
                            } else {
                                $pax += ($roomno['adult'] + $roomno['child']) - $HotelRoom->children;
                            }
                        } else {
                            $pax += $roomno['adult'];
                        }
                    }
                    $mData[$val->service_name_id]['tents'] += $val->total_rooms;
                    $mData[$val->service_name_id]['pax'] += $pax;
                    $totalData[$val->service_name_id]['totalTents'] += $val->total_rooms;
                    $totalData[$val->service_name_id]['totalPax'] += $pax;
                }
            }
            $MmtOrderMaster = DB::table("mmt_order_masters")->where(['status' => 'confirmed'])
                            ->whereIn('service_name_id', array_keys($MasterHotel))
                            ->where('start_date', '<=', $checkDate)
                            ->where('end_date', '>', $checkDate)
                            ->orderBy('service_name_id')
                            ->get();
            if (!empty($MmtOrderMaster)) {
                foreach ($MmtOrderMaster as $val) {
                    $pax = $tents = 0;
                    $HotelRoom = HotelRoom::where('mmt_room_id', $val->RoomTypeCode)->first();
                    $room_response = json_decode($val->response, 1);
                    $room_request = $room_response['Booking']['RoomStay']['Room'];
                    if ($val->total_rooms > 1) {
                        foreach ($room_request as $roomno) {
                            $add_child = 0;
                            if (isset($roomno['Age']) && is_array($roomno['Age'])) {
                                $filter_res = array_filter($roomno['Age'], function($n) { return $n > 6; });
                                if (!empty($filter_res)) { $add_child = count($filter_res); }
                            } elseif (isset($roomno['Age'])) {
                                $add_child = ($roomno['Age'] > 6) ? $roomno['Child'] : 0;
                            }
                            if ($roomno['Child'] > 0) {
                                if ($roomno['Child'] < $HotelRoom->children) {
                                    $pax += $roomno['Adult'] + $add_child;
                                } else {
                                    $pax += ($roomno['Adult'] + $roomno['Child'] + $add_child) - $HotelRoom->children;
                                }
                            } else {
                                $pax += $roomno['Adult'];
                            }
                        }
                    } else {
                        if ($val->total_child > 0) {
                            $add_child = 0;
                            if (isset($room_request['Age']) && is_array($room_request['Age'])) {
                                $filter_res = array_filter($room_request['Age'], function($n) { return $n > 6; });
                                if (!empty($filter_res)) { $add_child = count($filter_res); }
                            } elseif (isset($room_request['Age'])) {
                                $add_child = ($room_request['Age'] > 6) ? $room_request['Child'] : 0;
                            }
                            $pax += ($val->total_adults + $val->total_child + $add_child) - $HotelRoom->children;
                        } else {
                            $pax += $val->total_adults;
                        }
                    }
                    $mData[$val->service_name_id]['tents'] += $val->total_rooms;
                    $mData[$val->service_name_id]['pax'] += $pax;
                    $totalData[$val->service_name_id]['totalTents'] += $val->total_rooms;
                    $totalData[$val->service_name_id]['totalPax'] += $pax;
                }
            }
            $MisData['data'][$checkDate] = $mData;
        }
        $MisData['total'] = $totalData;
        $MisData['hotels'] = array_values($MasterHotel);
        // echo "<pre>";print_r($MisData);exit;
        return view('hotels.hotel-pax-report', compact('MisData', 'MasterHotel', 'start_date', 'end_date'));
    }

