                if (!empty($SubuserAccess)) {
                    $MasterHotelQuery->whereIn('id', array_values($SubuserAccess));
                }
            }
        }
        $bookFrom = 'all';
        $select = 'SUM(total_booked) AS totBook';
        $start_date = date("Y-m-d");
        $MasterHotel = $MasterHotelQuery->pluck('name', 'id')->toArray();
        $HotelList = array();
        if (isset($_GET['hotel_id']) && isset($_GET['check_date']) && isset($_GET['book_from'])) {
            $HotelList[$_GET['hotel_id']] = $MasterHotel[$_GET['hotel_id']];
            $start_date = date("Y-m-d", strtotime($_GET['check_date']));
            $bookFrom = $_GET['book_from'];
            if ($bookFrom == 'online') {
                $select = '(SUM(total_booked) - SUM(total_mmt_booking)) AS totBook';
            } elseif ($bookFrom == 'mmt') {
                $select = 'SUM(total_mmt_booking) AS totBook';
            } elseif ($bookFrom == 'all') {
                $select = 'SUM(total_booked) AS totBook';
            }
        } else {
            $HotelList = array_slice($MasterHotel, 0, 1, true);
        }
        $HotelId = 0;
        $MisData = array();
        foreach ($HotelList as $key => $value) {
            $HotelId = $key;
            $MisData['name'] = $value;
            $HotelRoom = HotelRoom::where(['hotel_id' => $key, 'status' => 'publish'])->orderBy('price', 'DESC')->get()->toArray();  // ->pluck('title', 'id')
            $roomData = array();
            if (!empty($HotelRoom)) {
                $roomIds = array_column($HotelRoom, 'id');
                $roomName = array_column($HotelRoom, 'title');
                $roomQty = array_column($HotelRoom, 'quantity');
                $MisData['rooms'] = array_combine($roomName, $roomQty);

                foreach ($HotelRoom as $room) {
                    $BeforeTodayQry = MasterInventory::select('room_id', DB::raw($select))
                                ->where('hotel_id', $key)
                                ->where('room_id', $room['id'])
                                ->where('date', '<', $start_date);
                    if ($vender_id == 3) {
                        $BeforeTodayQry->where('date', '>', $this->ecoStartDate);
                    }
                    $BeforeToday = $BeforeTodayQry->first()->toArray();
                    $MisData['before'][$room['id']] = 0;
                    if (!empty($BeforeToday['totBook'])) {
                        $MisData['before'][$room['id']] = $BeforeToday['totBook'];
                    }

                    $AllBookedQry = MasterInventory::select('room_id', DB::raw($select))
                                ->where('hotel_id', $key)
                                ->where('room_id', $room['id']);
                    if ($vender_id == 3) {
                        $AllBookedQry->where('date', '>', $this->ecoStartDate);
                    }
                    $AllBooked = $AllBookedQry->first()->toArray();

                    $MisData['allBooked'][$room['id']] = 0;
                    if (!empty($AllBooked['totBook'])) {
                        $MisData['allBooked'][$room['id']] = $AllBooked['totBook'];
                    }

                    $AllInitialQry = MasterInventory::select('room_id', DB::raw('SUM(initial_quantity) AS totBook'))
                                ->where('hotel_id', $key)
                                ->where('room_id', $room['id']);
                    if ($vender_id == 3) {
                        $AllInitialQry->where('date', '>', $this->ecoStartDate);
                    }
                    $AllInitial = $AllInitialQry->first()->toArray();

                    $MisData['allInitial'][$room['id']] = 0;
                    if (!empty($AllInitial['totBook'])) {
                        $MisData['allInitial'][$room['id']] = $AllInitial['totBook'];
                    }

                    $MasterInventoryQry = MasterInventory::where('hotel_id', $key)
                                    ->where('room_id', $room['id'])
                                    ->where('date', '>=', $start_date);
                    if ($vender_id == 3) {
                        $MasterInventoryQry->where('date', '>', $this->ecoStartDate);
                    }
                    $MasterInventory = $MasterInventoryQry->orderBy('date', 'ASC')->get();

                    foreach ($MasterInventory as $booked) {
                        $total_booked = 0;
                        if ($bookFrom == 'online') {
                            $total_booked = $booked->total_booked - $booked->total_mmt_booking;
                        } elseif ($bookFrom == 'mmt') {
                            $total_booked = $booked->total_mmt_booking;
                        } elseif ($bookFrom == 'all') {
                            $total_booked = $booked->total_booked;
                        }
                        $roomData[$booked->date][$room['id']] = $total_booked;
                    }
                }
            }
            $MisData['data'] = $roomData;
        }
        // echo "<pre>";print_r($MisData);exit;
        return view('hotels.hotel-book-count-report', compact('MisData', 'MasterHotel', 'HotelId', 'start_date', 'bookFrom'));
    }

