                        ->get();
                    foreach ($MasterInventory as $data) {

                        $OrderDetail = OrderDetail::select(DB::raw('SUM(service_item_quantity) as totBooked'))
                            ->where('status', 'completed')
                            ->where('service_name_id', $hotelId)
                            ->where('service_item_id', $key)
                            ->whereRaw("(service_type = 'hotel' OR service_type = 'package')")
                            // ->whereDate('start_date', date("Y-m-d", strtotime($data->date)))
                            ->where('start_date', '<=', $data->date)
                            ->where('end_date', '>', $data->date)
                            ->groupBy('service_item_id')
                            ->first();
                        $OrderDetail = ['totBooked' => $OrderDetail->totBooked ?? 0];

                        $MmtOrders = DB::table('mmt_order_masters')
                            ->join('hotel_rooms', 'mmt_order_masters.RoomTypeCode', '=', 'hotel_rooms.mmt_room_id')
                            ->select(DB::raw('SUM(mmt_order_masters.total_rooms) as totmmtBooked'))
                            ->where('hotel_rooms.id', $key)
                            ->where('mmt_order_masters.service_name_id', $hotelId)
                            // ->whereDate('mmt_order_masters.start_date', date("Y-m-d", strtotime($data->date)))
                            ->where('mmt_order_masters.start_date', '<=', $data->date)
                            ->where('mmt_order_masters.end_date', '>', $data->date)
                            ->where('mmt_order_masters.status', 'confirmed')
                            ->first();
                        $MmtOrders = ['totmmtBooked' => $MmtOrders->totmmtBooked ?? 0];

                        $MisData[$data->date][$value] = array('total_actual_booked' => $OrderDetail['totBooked'] + $MmtOrders['totmmtBooked'], 'total_booked' => $data->total_booked);


                        if (!isset($MisData[$data->date]['Total'])) {
                            $MisData[$data->date]['Total'] = [
                                'total_actual_booked' => 0,
                                'total_booked' => 0
                            ];
                        }

                        $MisData[$data->date]['Total']['total_actual_booked'] += $OrderDetail['totBooked'] + $MmtOrders['totmmtBooked'];
                        $MisData[$data->date]['Total']['total_booked'] += $data->total_booked;

                    }
                }
                foreach ($MisData as $date => $rooms) {
                    if (isset($rooms['Total'])) {
                        $totalData = $rooms['Total'];
                        unset($MisData[$date]['Total']);
                        $MisData[$date]['Total'] = $totalData;
                    }
                }
            }
            $MisHotelData[$hotel_name] = array('data' => $MisData, 'rooms' => array_values($hotelRooms));
        }
        // echo '<pre>';print_r($MisHotelData); exit;

        return view('hotels.booking-comparison-report', compact('MasterHotel', 'MisHotelData', 'HotelId', 'start_date', 'end_date'));
    }

