                    ->join('order_details AS OD', 'OM.id', '=', 'OD.order_master_id')
                    ->where(['OM.status' => 'completed'])
                    ->whereRaw("(OM.service_type = 'hotel' OR OM.service_category = 'package')")
                    ->whereIn('OD.service_name_id', array_keys($HotelList))
                    ->where('OD.start_date', '<=', $check_date)
                    ->where('OD.end_date', '>', $check_date)
                    ->select('OM.*')
                    ->groupBy('OM.id')
                    ->get();
            if (!empty($Orders->toArray())) {
                foreach ($Orders as $key => $value) {
                    $hotelId = $hotelName = $rooms = $start_date = $end_date = '';$night = $total_occ = 0;
                    if ($value->service_type == 'hotel') {
                        $room_request = json_decode($value->room_request, 1);
                        foreach ($room_request as $roomno) {
                            $HotelRoom = HotelRoom::find($roomno['id']);
                            if ($roomno['child'] > 0) {
                                if ($roomno['child'] < $HotelRoom->children) {
                                    $total_occ += $roomno['adult'];
                                } else {
                                    $total_occ += ($roomno['adult'] + $roomno['child']) - $HotelRoom->children;
                                }
                            } else {
                                $total_occ += $roomno['adult'];
                            }
                        }
                        $room_details = json_decode($value->room_details, 1);
                        foreach ($room_details as $room) {
                            $rooms .= $room['quantity'] . ' ' . $room['room_name'] . ',';
                        }
                        $rooms = rtrim($rooms, ',');
                        $difference = strtotime($value->end_date) - strtotime($value->start_date);
                        $days = round($difference / (60 * 60 * 24));
                        $night = ($days == 0) ? 1 : $days;
                        $start_date = date("d-M-Y", strtotime($value->start_date));
                        $end_date = date("d-M-Y", strtotime($value->end_date));
                        $hotelId = $value->service_name_id;
                        $hotelName = $value->service_name;
                    } else {
                        $OrderDetail = OrderDetail::select('service_item_name', 'start_date', 'end_date', 'service_name_id', 'service_name', DB::raw('sum(service_item_quantity) as totBooked'))->where(['order_master_id' => $value->id, 'start_date' => $check_date])->groupBy('service_item_id')->first();
                        if (empty($OrderDetail)) {
                            continue;
                        }
                        $rooms = $OrderDetail->totBooked .' '. $OrderDetail->service_item_name;
                        $start_date = date("d-M-Y", strtotime($OrderDetail->start_date));
                        $end_date = date("d-M-Y", strtotime($OrderDetail->end_date));
