    public function hotelCancelReport(Request $request)
    {
        if (!(parent::checkViewPrivilege(87))) {
            Session::flash('success', 'You are not autherised to view this page.');
            return redirect()->back();
        }
        $vender_id = 0;
        $MasterHotelQuery = DB::table("master_hotels"); // MasterHotel::where('status', 'publish');
        if (Auth::user()->access_type == 'vendor') {
            $vender_id = (Auth::user()->role == 2) ? Auth::user()->id : Auth::user()->vendor_id;
            $MasterHotelQuery->where('vender_id', $vender_id);
            if ((Auth::user()->role == 3)) {
                $SubuserAccess = SubuserAccess::where(['user_id' => Auth::user()->id, 'service' => 'hotel'])->pluck('service_id', 'id')->toArray();
                if (!empty($SubuserAccess)) {
                    $MasterHotelQuery->whereIn('id', array_values($SubuserAccess));
                }
            }
        }
        $MasterHotel = $MasterHotelQuery->pluck('name', 'id')->toArray();
        $start_date = date("Y-m-d", strtotime('-30 Days'));
        if ($vender_id == 3) {
            $start_date = $this->ecoStartDate;
        }
        $end_date = date("Y-m-d");
        $MisHotelData = array();
        $HotelId = 0;
        $HotelList = array();
        if (isset($_GET['check_date']) && isset($_GET['hotel_id'])) {
            $HotelId = $_GET['hotel_id'];
            $check_date = explode(' - ', $_GET['check_date']);
            $start_date = date("Y-m-d", strtotime($check_date[0]));
            $end_date = date("Y-m-d", strtotime($check_date[1]));

            if ($HotelId != 0 && isset($MasterHotel[$HotelId])) {
                $HotelList[$HotelId] = $MasterHotel[$HotelId];
            } else {
                $HotelList = $MasterHotel;
            }
        } else {
            $HotelList = $MasterHotel;
        }
        $Orders = OrderMaster::where(['service_type' => 'hotel', 'status' => 'cancelled', 'payment_status' => 'success'])
                    ->whereIn('service_name_id', array_keys($HotelList))
                    ->whereBetween('cancel_date', [$start_date .' 00:00:00', $end_date .' 23:59:59'])
                    ->orderBy('cancel_date', 'DESC')
                    ->get();
        if (!empty($Orders->toArray())) {
            foreach ($Orders as $key => $value) {
                $room_details = json_decode($value->room_details, 1);
                $rooms = '';
                foreach ($room_details as $room) {
                    $rooms .= $room['quantity'] . ' ' . $room['room_name'] . ',';
                }
                $rooms = rtrim($rooms, ',');
                $difference = strtotime($value->end_date) - strtotime($value->start_date);
                $days = round($difference / (60 * 60 * 24));
                $night = ($days == 0) ? 1 : $days;

                $MisHotelData[$value->service_name_id]['data'][] = array(
                    'invoice_id' => $value->invoice_id,
                    'oderID' => $value->id,
                    'book_date' => date("d-M-Y", strtotime($value->created_at)),
                    'cancel_date' => date("d-M-Y", strtotime($value->cancel_date)),
                    'cancel_time' => date("h:i a", strtotime($value->cancel_date)),
                    'guest_name' => $value->customer_name,
                    'guest_phone' => $value->customer_phone,
                    'guest_email' => $value->customer_email,
                    'unit_name' => $value->service_name,
                    'rooms' => $rooms,
                    'check_in' => date("d-M-Y", strtotime($value->start_date)),
                    'check_out' => date("d-M-Y", strtotime($value->end_date)),
                    'nights' => $night,
                    'total_amount' => $value->total_order_price,
                    'refund_amount' => $value->refund_amount,
                    'order_type' => $value->order_type,
                    'cancel_voucher' => $value->cancel_voucher,
                    'platform' => 'website'
                );
                $MisHotelData[$value->service_name_id]['name'] = $value->service_name;
            }
        }
        $MmtOrders = DB::table('mmt_order_masters')
                    ->whereIn('service_name_id', array_keys($HotelList))
                    ->whereBetween('cancel_date', [$start_date .' 00:00:00', $end_date .' 23:59:59'])
                    ->where('status', 'cancelled')
                    ->orderBy('cancel_date', 'DESC')
                    ->get();
        if (!empty($MmtOrders->toArray())) {
            foreach ($MmtOrders as $key => $value) {
                // $room_details = json_decode($value->room_details, 1);
                // $rooms = $room_details[0]['quantity'] .' '. $room_details[0]['name'];
                $rooms = $value->total_rooms .' '. $value->RoomTypeName;
                // $rooms = '';
                // foreach ($room_details as $room) {
                //     $rooms .= $room['quantity'] . ' ' . $room['room_name'] . ',';
                // }
                // $rooms = rtrim($rooms, ',');
                $difference = strtotime($value->end_date) - strtotime($value->start_date);
                $days = round($difference / (60 * 60 * 24));
                $night = ($days == 0) ? 1 : $days;

                $MisHotelData[$value->service_name_id]['data'][] = array(
                    'invoice_id' => $value->order_id,
                    'oderID' => $value->id,
                    'book_date' => date("d-M-Y", strtotime($value->booking_date)),
                    'cancel_date' => date("d-M-Y", strtotime($value->cancel_date)),
                    'cancel_time' => date("h:i a", strtotime($value->last_modified_time)),
                    'guest_name' => $value->customer_name,
                    'guest_phone' => $value->customer_phone,
                    'guest_email' => $value->customer_email,
                    'unit_name' => $value->service_name,
                    'rooms' => $rooms,
                    'check_in' => date("d-M-Y", strtotime($value->start_date)),
                    'check_out' => date("d-M-Y", strtotime($value->end_date)),
                    'nights' => $night,
                    'total_amount' => $value->total_order_price,
                    'refund_amount' => $value->refund_amount,
                    'order_type' => $value->booking_vendor_name,
                    'cancel_voucher' => $value->cancel_voucher,
                    'platform' => 'ota'
                );
                $MisHotelData[$value->service_name_id]['name'] = $value->service_name;
            }
        }

        return view('hotels.hotel-cancel-report', compact('MisHotelData', 'start_date', 'end_date', 'MasterHotel', 'HotelId'));
    }

    public function agentHotelReport(Request $request)
    {
        if (!(parent::checkViewPrivilege(89))) {
            Session::flash('success', 'You are not autherised to view this page.');
            return redirect()->back();
        }
        $vender_id = 0;
        $MasterHotelQuery = DB::table("master_hotels"); // MasterHotel::where('status', 'publish');
        if (Auth::user()->access_type == 'vendor') {
            $vender_id = (Auth::user()->role == 2) ? Auth::user()->id : Auth::user()->vendor_id;
            $MasterHotelQuery->where('vender_id', $vender_id);
            if ((Auth::user()->role == 3)) {
                $SubuserAccess = SubuserAccess::where(['user_id' => Auth::user()->id, 'service' => 'hotel'])->pluck('service_id', 'id')->toArray();
                if (!empty($SubuserAccess)) {
                    $MasterHotelQuery->whereIn('id', array_values($SubuserAccess));
                }
            }
        }
        $MasterHotel = $MasterHotelQuery->pluck('id')->toArray();

        $start_date = date("Y-m-d", strtotime('-30 Days'));
        if ($vender_id == 3) {
            $start_date = $this->ecoStartDate;
        }
        $end_date = date("Y-m-d");
        $report_type = 'book_date';
        $MisHotelData = array();

        if (isset($_GET['check_date'])) {
            $report_type = $_GET['report_type'];
            $check_date = explode(' - ', $_GET['check_date']);
            $start_date = date("Y-m-d", strtotime($check_date[0]));
            $end_date = date("Y-m-d", strtotime($check_date[1]));
        }
        $filter_column = ($report_type == 'book_date') ? 'OM.created_at' : 'OM.start_date';
        foreach ($MasterHotel as $hotelId) {
            $Orders = DB::table('order_masters AS OM')
                    ->join('users AS U', 'OM.customer_id', '=', 'U.id')
                    ->select('OM.service_name', 'OM.customer_id', DB::raw('CONCAT(U.first_name, "  ", U.last_name) as agent'), DB::raw('SUM(DATEDIFF(OM.end_date, OM.start_date) * OM.total_rooms) as roomNights'))
                    ->where(['OM.status' => 'completed', 'U.role' => 3, 'U.access_type' => 'agent', 'OM.service_name_id' => $hotelId, 'OM.service_type' => 'hotel'])
                    ->whereBetween($filter_column, [$start_date .' 00:00:00', $end_date .' 23:59:59'])
                    ->groupBy('OM.customer_id')
                    ->get();
            if (!empty($Orders->toArray())) {
                foreach($Orders as $data) {
                    $MisHotelData[$hotelId][] = array(
                        'unit_name' => $data->service_name,
                        'agent_name' => $data->agent,
                        'room_night' => $data->roomNights,
                    );
                }
            }
        }

        return view('hotels.agent-hotel-report', compact('MisHotelData', 'start_date', 'end_date', 'report_type'));
    }

