    public function insertMasterInventory()
    {
        $today = date("Y-m-d");
        //$end_date = date("Y-m-d", strtotime($today .' +120 days'));
        $end_date = date("Y-m-d", strtotime($today .' +90 days'));

        $HotelRooms = HotelRoom::get();
        foreach ($HotelRooms as $value) {
            $inventory = array();
            $MasterHotel = MasterHotel::where('id', $value->hotel_id)->where('vender_id', '!=', 3)->where('vender_id', '!=', 58672)->first();
            if (empty($MasterHotel)) {
                continue;
            }
            // $ExistingInventory = MasterInventory::where('room_id', $value->id)->orderBy('date', 'DESC')->first();
            // if (!empty($ExistingInventory)) {
            //     $today = date("Y-m-d", strtotime($ExistingInventory->date . ' +1 days'));
            // }
            $difference = strtotime($end_date) - strtotime($today);
            $days = ($end_date == $today) ? 0 : round($difference / (60 * 60 * 24));
            $roomPrice = $value->price;
            $count = 0;
            for ($i = 0; $i <= $days; $i++) {
                $date = date("Y-m-d", strtotime($today . ' + ' . $i . ' days'));
                $ExistingInventory = MasterInventory::where(['room_id' => $value->id, 'date' => $date])->first();
                if (empty($ExistingInventory)) {
                        $BlockData = HotelSale::where('hotel_id', $MasterHotel->id)
                        ->where('start_date', '<=', $date)
                        ->where('end_date', '>=', $date)
                        // ->where('room_id', $value->id)
                        ->get()->toarray();
                    if (empty($BlockData)) {
                        $RoomAvailability = HotelAvailability::select(DB::raw('SUM(quantity) AS totBlocked'))->where(['room_id' => $value->id, 'block_date' => $date])->first();
                        $total_blocked = 0;
                        $total_available = $value->quantity;
                        $total_blocked = (!empty($RoomAvailability->totBlocked)) ? $RoomAvailability->totBlocked : 0;
                        $total_available = $value->quantity - $total_blocked;
                        if ($total_available < 0) {
                            $total_available = 0;
                            $total_blocked = $value->quantity;
                        }
                        $inventory[$count] = [
                            'vendor_id' => $MasterHotel->vender_id,
                            'hotel_id' => $MasterHotel->id,
                            'room_id' => $value->id,
                            'date' => $date,
                            'initial_quantity' => $value->quantity,
                            'total_available' => $total_available,
                            'total_booked' => 0,
                            'total_blocked' => $total_blocked,
                            'total_online_completed' => 0,
                            'total_online_pending' => 0,
                            'total_offline_completed' => 0,
                            'total_offline_pending' => 0,
                            'total_tour_booking' => 0,
                            'total_mmt_booking' => 0
                        ];
                        $PricingData = HotelRoomPricing::where(['hotel_id' => $MasterHotel->id, 'room_id' => $value->id, 'start_date' => $date])->first();
                        if (!empty($PricingData)) {
                            if ($PricingData->offer_type == 'minus') {
                                $roomPrice -= $PricingData->offer_percentage;
                            } else {
                                $roomPrice += $PricingData->offer_percentage;
                            }
                        }
                        $FullBlockData = BlockedHotel::where(['hotel_id' => $MasterHotel->id, 'block_date' => $date])
                                        ->whereRaw("find_in_set('". $value->id ."',rooms)")
                                        ->first();
                        if (!empty($MasterHotel->mmt_hotel_id) && !empty($value->mmt_room_id)) {
                            $DataToSend = '';
                            $InvRateplanData = MmtRatePlans::where(['room_type_code' => $value->mmt_room_id, 'is_active' => 'true'])->first();
                            if (!empty($InvRateplanData)) {
                                if ($InvRateplanData->rate_plan_code && $value->adults > 0) {
                                    $DataToSend .= '<Rate currencyCode="INR" code="'. $InvRateplanData->rate_plan_code .'" rateType="b2c">
                                                <PerOccupancyRates>';
                                    if ($value->adults > 1) {
                                        for ($j = 1; $j <= $value->adults; $j++) {
                                            $DataToSend .= '<PerOccupancy occupancy="'. $j .'" rate="'. $roomPrice .'" />';
                                        }
                                    } else if ($value->adults == 1) {
                                        $DataToSend .= '<PerOccupancy occupancy="1" rate="' . $roomPrice . '" />';
                                    }
                                    $DataToSend .= '</PerOccupancyRates>';

                                    if ($value->extra_bed_allowed > 0 && $value->extra_bed_price > 0) {
                                        $DataToSend .= '<AdditionalGuestRates>
                                                            <AdditionalGuestRate type="Adult" rate="'. $value->extra_bed_price .'" />
                                                            <AdditionalGuestRate type="Child" ageRange="1" rate="0" />
                                                            <AdditionalGuestRate type="Child" ageRange="2" rate="'. $value->extra_bed_price .'" />
                                                            <AdditionalGuestRate type="Child" ageRange="3" rate="'. $value->extra_bed_price .'" />
                                                        </AdditionalGuestRates>';
                                    }
                                    $DataToSend .= '</Rate>';
                                }
                            }
                            $closed = "false";
                            $BlockedMmt = BlockedMmtInventory::where('hotel_id', $MasterHotel->id)
                                        ->where('block_date', $date)
                                        ->where('rooms', $value->id)
                                        ->whereRaw("(platform LIKE 'all' OR platform LIKE 'mmt')")
                                        ->get()->toArray();
                            if (!empty($FullBlockData) || !empty($BlockedMmt)) {
                                $closed = "true";
                            }
                            $Xml = '<?xml version="1.0" encoding="UTF-8" ?>
                                        <AvailRateUpdateRQ hotelCode="'. $MasterHotel->mmt_hotel_id .'" timeStamp="'. time() .'">
                                            <AvailRateUpdate locatorID="1">
                                                <DateRange from="'. $date . '" to="' . $date .'"/>
                                                <Availability code="'. $value->mmt_room_id .'" count="'. $total_available .'" closed="'. $closed .'" />
                                                '. $DataToSend .'
                                            </AvailRateUpdate>
                                        </AvailRateUpdateRQ>';
                            DB::insert("INSERT INTO `mmt_availability_logs`(`request_source`, `vendor_id`, `hotel_id`, `hotel_code`, `room_id`, `room_code`, `request_data`, `status`, `created_at`, `request_type`, `quantity`, `date`) VALUES ('inventory_cron', '". $MasterHotel->vender_id ."', '". $MasterHotel->id ."', '". $MasterHotel->mmt_hotel_id ."', '". $value->id ."', '". $value->mmt_room_id . "', '". $Xml ."', '0', '" . date('Y-m-d H:i:s') ."', 'rate', '". $total_available ."', '". $date ."')");
                        }
                        if (!empty($MasterHotel->ctp_hotel_id) && !empty($value->ctp_room_id)) {
                            $closed = "Open";
                            $BlockedMmt = BlockedMmtInventory::where('hotel_id', $MasterHotel->id)
                                        ->where('block_date', $date)
                                        ->where('rooms', $value->id)
                                        ->whereRaw("(platform LIKE 'all' OR platform LIKE 'cleartrip')")
                                        ->get()->toArray();
                            if (!empty($FullBlockData) || !empty($BlockedMmt)) {
                                $closed = "Close";
                            }
                            $DataToSend = '';
                            $InvRateplanData = CtpRatePlans::where(['room_type_code' => $value->ctp_room_id])->first();
                            if (!empty($InvRateplanData)) {
                                if ($InvRateplanData->rate_plan_code && $value->adults > 0) {
                                    // Availability
                                    $Xml = '<OTA_HotelAvailNotifRQ xmlns="http://www.opentravel.org/OTA/2003/05" Version="1.0" EchoToken="1234">
                                                <AvailStatusMessages HotelCode="'. $MasterHotel->ctp_hotel_id .'">
                                                <AvailStatusMessage BookingLimit="'. $total_available .'">
                                                    <StatusApplicationControl Start="'. $date .'" End="'. $date .'" InvTypeCode="'. $value->ctp_room_id .'" RatePlanCode="'. $InvRateplanData->rate_plan_code .'" />
                                                    <RestrictionStatus Status="'. $closed .'" />
                                                </AvailStatusMessage>
                                                </AvailStatusMessages>
                                            </OTA_HotelAvailNotifRQ>';
                                    DB::insert("INSERT INTO `ctp_availability_logs`(`request_source`, `vendor_id`, `hotel_id`, `hotel_code`, `room_id`, `room_code`, `request_data`, `status`, `created_at`, `request_type`, `quantity`, `date`) VALUES ('inventory_cron', '". $MasterHotel->vender_id ."', '". $MasterHotel->id ."', '". $MasterHotel->ctp_hotel_id ."', '". $value->id ."', '". $value->ctp_room_id . "', '". $Xml ."', '0', '" . date('Y-m-d H:i:s') ."', 'inventory', '". $total_available ."', '". $date ."')");
                                    // Rate Plan
                                    $base_plan = $additional_plan = '';
                                    if ($value->adults > 1) {
                                        for ($j = 1; $j <= $value->adults; $j++) {
                                            $base_plan .= '<BaseByGuestAmt AgeQualifyingCode="10" NumberOfGuests="'. $j .'" AmountBeforeTax="'. $roomPrice .'"/>';
                                        }
                                    } else if ($value->adults == 1) {
                                        $base_plan .= '<BaseByGuestAmt AgeQualifyingCode="10" NumberOfGuests="1" AmountBeforeTax="'. $roomPrice .'"/>';
                                    }
                                    if ($value->extra_bed_allowed > 0 && $value->extra_bed_price > 0) {
                                        $additional_plan .= '<AdditionalGuestAmounts>
                                                                <AdditionalGuestAmount AgeQualifyingCode="10" Amount="'. $value->extra_bed_price .'"/>
                                                                <AdditionalGuestAmount AgeQualifyingCode="8" Amount="'. $value->extra_bed_price .'"/>
                                                                <AdditionalGuestAmount AgeQualifyingCode="6" Amount="0"/>
                                                            </AdditionalGuestAmounts>';
                                    }
                                    $xml = '<OTA_HotelRateAmountNotifRQ xmlns="http://www.opentravel.org/OTA/2003/05" Version="1.0" EchoToken="1234">
                                                <RateAmountMessages HotelCode="'. $MasterHotel->ctp_hotel_id .'">
                                                    <RateAmountMessage>
                                                        <StatusApplicationControl Start="'. $date .'" End="'. $date .'" InvTypeCode="'. $value->ctp_room_id .'" RatePlanCode="'. $InvRateplanData->rate_plan_code .'" />
                                                        <Rates>
                                                            <Rate>
                                                                <BaseByGuestAmts>
                                                                    '. $base_plan .'
                                                                </BaseByGuestAmts>
                                                                '. $additional_plan .'
                                                            </Rate>
                                                        </Rates>
                                                    </RateAmountMessage>
                                                </RateAmountMessages>
                                            </OTA_HotelRateAmountNotifRQ>';

                                    DB::insert("INSERT INTO `ctp_availability_logs`(`request_source`, `vendor_id`, `hotel_id`, `hotel_code`, `room_id`, `room_code`, `request_data`, `status`, `created_at`, `request_type`, `quantity`, `date`) VALUES ('inventory_cron', '". $MasterHotel->vender_id ."', '". $MasterHotel->id ."', '". $MasterHotel->ctp_hotel_id ."', '". $value->id ."', '". $value->ctp_room_id . "', '". $xml ."', '0', '" . date('Y-m-d H:i:s') . "', 'rate', '". $total_available ."', '". $date ."')");
                                }
                            }
                        }
                    }
                }
                $count++;
            }
            $MasterInventory = MasterInventory::insert($inventory);
        }
        echo "Inventory added sussceefully.";
        exit;
    }

    public function insertCustomInventory($vendor_id = null, $start_date = null, $end_date = null, $hotel_id = null)
    {
        $today = date("Y-m-d", strtotime($start_date));
        $end_date = date("Y-m-d", strtotime($end_date));
        $AllHotelQry = MasterHotel::where('vender_id', $vendor_id);
        if (!is_null($hotel_id) && $hotel_id != 0) {
            $AllHotelQry->where('id', $hotel_id);
        }
        $AllHotel = $AllHotelQry->get();
        if ($end_date >= $today && !empty($AllHotel->toArray())) {
            $difference = strtotime($end_date) - strtotime($today);
            $days = ($end_date == $today) ? 0 : round($difference / (60 * 60 * 24));
            foreach ($AllHotel as $MasterHotel) {
                $HotelRooms = HotelRoom::where('hotel_id', $MasterHotel->id)->get();
                foreach ($HotelRooms as $value) {
                    $inventory = array();
                    $ExistingInventory = MasterInventory::where('room_id', $value->id)->where('date', '>=', $today)->pluck('room_id', 'date')->toArray();
                    $count = 0;
                    $roomPrice = $value->price;
                    for ($i = 0; $i <= $days; $i++) {
                        $date = date("Y-m-d", strtotime($today . ' + ' . $i . ' days'));

                        if (!array_key_exists($date, $ExistingInventory)) {
                            $BlockData = HotelSale::where('hotel_id', $MasterHotel->id)
                                ->where('start_date', '<=', $date)
                                ->where('end_date', '>=', $date)
                                // ->where('room_id', $value->id)
                                ->get()->toarray();
                            if (empty($BlockData)) {
                                $RoomAvailability = HotelAvailability::select(DB::raw('SUM(quantity) AS totBlocked'))->where(['room_id' => $value->id, 'block_date' => $date])->first();
                                $total_blocked = 0;
                                $total_available = $value->quantity;
                                $total_blocked = (!empty($RoomAvailability->totBlocked)) ? $RoomAvailability->totBlocked : 0;
                                $total_available = $value->quantity - $total_blocked;
                                if ($total_available < 0) {
                                    $total_available = 0;
                                    $total_blocked = $value->quantity;
                                }
                                $inventory[$count] = [
                                    'vendor_id' => $MasterHotel->vender_id,
                                    'hotel_id' => $MasterHotel->id,
                                    'room_id' => $value->id,
                                    'date' => $date,
                                    'initial_quantity' => $value->quantity,
                                    'total_available' => $total_available,
                                    'total_booked' => 0,
                                    'total_blocked' => $total_blocked,
                                    'total_online_completed' => 0,
                                    'total_online_pending' => 0,
                                    'total_offline_completed' => 0,
                                    'total_offline_pending' => 0,
                                    'total_tour_booking' => 0,
                                    'total_mmt_booking' => 0
                                ];
                                $PricingData = HotelRoomPricing::where(['hotel_id' => $MasterHotel->id, 'room_id' => $value->id, 'start_date' => $date])->first();
                                if (!empty($PricingData)) {
                                    if ($PricingData->offer_type == 'minus') {
                                        $roomPrice -= $PricingData->offer_percentage;
                                    } else {
                                        $roomPrice += $PricingData->offer_percentage;
                                    }
                                }
                                $FullBlockData = BlockedHotel::where(['hotel_id' => $MasterHotel->id, 'block_date' => $date])
                                                    ->whereRaw("find_in_set('". $value->id ."',rooms)")
                                                    ->first();
                                if (!empty($MasterHotel->mmt_hotel_id) && !empty($value->mmt_room_id)) {
                                    $DataToSend = '';
                                    $InvRateplanData = MmtRatePlans::where(['room_type_code' => $value->mmt_room_id, 'is_active' => 'true'])->first();
                                    if (!empty($InvRateplanData)) {
                                        if ($InvRateplanData->rate_plan_code && $value->adults > 0) {
                                            $DataToSend .= '<Rate currencyCode="INR" code="'. $InvRateplanData->rate_plan_code .'" rateType="b2c">
                                                        <PerOccupancyRates>';
                                            if ($value->adults > 1) {
                                                for ($j = 1; $j <= $value->adults; $j++) {
                                                    $DataToSend .= '<PerOccupancy occupancy="'. $j .'" rate="'. $roomPrice .'" />';
                                                }
                                            } else if ($value->adults == 1) {
                                                $DataToSend .= '<PerOccupancy occupancy="1" rate="' . $roomPrice . '" />';
                                            }
                                            $DataToSend .= '</PerOccupancyRates>';

                                            if ($value->extra_bed_allowed > 0 && $value->extra_bed_price > 0) {
                                                $DataToSend .= '<AdditionalGuestRates>
                                                                    <AdditionalGuestRate type="Adult" rate="'. $value->extra_bed_price .'" />
                                                                    <AdditionalGuestRate type="Child" ageRange="1" rate="0" />
                                                                    <AdditionalGuestRate type="Child" ageRange="2" rate="'. $value->extra_bed_price .'" />
                                                                    <AdditionalGuestRate type="Child" ageRange="3" rate="'. $value->extra_bed_price .'" />
                                                                </AdditionalGuestRates>';
                                            }
                                            $DataToSend .= '</Rate>';
                                        }
                                    }
                                    $closed = "false";
                                    $BlockedMmt = BlockedMmtInventory::where('hotel_id', $MasterHotel->id)
                                                ->where('block_date', $date)
                                                ->where('rooms', $value->id)
                                                ->whereRaw("(platform LIKE 'all' OR platform LIKE 'mmt')")
                                                ->get()->toArray();
                                    if (!empty($FullBlockData) || !empty($BlockedMmt)) {
                                        $closed = "true";
                                    }
                                    $Xml = '<?xml version="1.0" encoding="UTF-8" ?>
                                                <AvailRateUpdateRQ hotelCode="'. $MasterHotel->mmt_hotel_id .'" timeStamp="'. time() .'">
                                                    <AvailRateUpdate locatorID="1">
                                                        <DateRange from="'. $date . '" to="' . $date .'"/>
                                                        <Availability code="'. $value->mmt_room_id .'" count="'. $total_available .'" closed="'. $closed .'" />
                                                        '. $DataToSend .'
                                                    </AvailRateUpdate>
                                                </AvailRateUpdateRQ>';
                                    DB::insert("INSERT INTO `mmt_availability_logs`(`request_source`, `vendor_id`, `hotel_id`, `hotel_code`, `room_id`, `room_code`, `request_data`, `status`, `created_at`, `request_type`, `quantity`, `date`) VALUES ('custom_inventory_cron', '". $MasterHotel->vender_id ."', '". $MasterHotel->id ."', '". $MasterHotel->mmt_hotel_id ."', '". $value->id ."', '". $value->mmt_room_id . "', '". $Xml ."', '0', '" . date('Y-m-d H:i:s') . "', 'rate', '". $total_available ."', '". $date ."')");
                                }
                                if (!empty($MasterHotel->ctp_hotel_id) && !empty($value->ctp_room_id)) {
                                    $closed = "Open";
                                    $BlockedMmt = BlockedMmtInventory::where('hotel_id', $MasterHotel->id)
                                                ->where('block_date', $date)
                                                ->where('rooms', $value->id)
                                                ->whereRaw("(platform LIKE 'all' OR platform LIKE 'cleartrip')")
                                                ->get()->toArray();
                                    if (!empty($FullBlockData) || !empty($BlockedMmt)) {
                                        $closed = "Close";
                                    }
                                    $DataToSend = '';
                                    $InvRateplanData = CtpRatePlans::where(['room_type_code' => $value->ctp_room_id])->first();
                                    if (!empty($InvRateplanData)) {
                                        if ($InvRateplanData->rate_plan_code && $value->adults > 0) {
                                            // Availability
                                            $Xml = '<OTA_HotelAvailNotifRQ xmlns="http://www.opentravel.org/OTA/2003/05" Version="1.0" EchoToken="1234">
                                                        <AvailStatusMessages HotelCode="'. $MasterHotel->ctp_hotel_id .'">
                                                        <AvailStatusMessage BookingLimit="'. $total_available .'">
                                                            <StatusApplicationControl Start="'. $date .'" End="'. $date .'" InvTypeCode="'. $value->ctp_room_id .'" RatePlanCode="'. $InvRateplanData->rate_plan_code .'" />
                                                            <RestrictionStatus Status="'. $closed .'" />
                                                        </AvailStatusMessage>
                                                        </AvailStatusMessages>
                                                    </OTA_HotelAvailNotifRQ>';
                                            DB::insert("INSERT INTO `ctp_availability_logs`(`request_source`, `vendor_id`, `hotel_id`, `hotel_code`, `room_id`, `room_code`, `request_data`, `status`, `created_at`, `request_type`, `quantity`, `date`) VALUES ('inventory_cron', '". $MasterHotel->vender_id ."', '". $MasterHotel->id ."', '". $MasterHotel->ctp_hotel_id ."', '". $value->id ."', '". $value->ctp_room_id . "', '". $Xml ."', '0', '" . date('Y-m-d H:i:s') . "', 'inventory', '". $total_available ."', '". $date ."')");
                                            // Rate Plan
                                            $base_plan = $additional_plan = '';
                                            if ($value->adults > 1) {
                                                for ($j = 1; $j <= $value->adults; $j++) {
                                                    $base_plan .= '<BaseByGuestAmt AgeQualifyingCode="10" NumberOfGuests="'. $j .'" AmountBeforeTax="'. $roomPrice .'"/>';
                                                }
                                            } else if ($value->adults == 1) {
                                                $base_plan .= '<BaseByGuestAmt AgeQualifyingCode="10" NumberOfGuests="1" AmountBeforeTax="'. $roomPrice .'"/>';
                                            }
                                            if ($value->extra_bed_allowed > 0 && $value->extra_bed_price > 0) {
                                                $additional_plan .= '<AdditionalGuestAmounts>
                                                                        <AdditionalGuestAmount AgeQualifyingCode="10" Amount="'. $value->extra_bed_price .'"/>
                                                                        <AdditionalGuestAmount AgeQualifyingCode="8" Amount="'. $value->extra_bed_price .'"/>
                                                                        <AdditionalGuestAmount AgeQualifyingCode="6" Amount="0"/>
                                                                    </AdditionalGuestAmounts>';
                                            }
                                            $xml = '<OTA_HotelRateAmountNotifRQ xmlns="http://www.opentravel.org/OTA/2003/05" Version="1.0" EchoToken="1234">
                                                        <RateAmountMessages HotelCode="'. $MasterHotel->ctp_hotel_id .'">
                                                            <RateAmountMessage>
                                                                <StatusApplicationControl Start="'. $date .'" End="'. $date .'" InvTypeCode="'. $value->ctp_room_id .'" RatePlanCode="'. $InvRateplanData->rate_plan_code .'" />
                                                                <Rates>
                                                                    <Rate>
                                                                        <BaseByGuestAmts>
                                                                            '. $base_plan .'
                                                                        </BaseByGuestAmts>
                                                                        '. $additional_plan .'
                                                                    </Rate>
                                                                </Rates>
                                                            </RateAmountMessage>
                                                        </RateAmountMessages>
                                                    </OTA_HotelRateAmountNotifRQ>';

                                            DB::insert("INSERT INTO `ctp_availability_logs`(`request_source`, `vendor_id`, `hotel_id`, `hotel_code`, `room_id`, `room_code`, `request_data`, `status`, `created_at`, `request_type`, `quantity`, `date`) VALUES ('inventory_cron', '". $MasterHotel->vender_id ."', '". $MasterHotel->id ."', '". $MasterHotel->ctp_hotel_id ."', '". $value->id ."', '". $value->ctp_room_id . "', '". $xml ."', '0', '" . date('Y-m-d H:i:s') . "', 'rate', '". $total_available ."', '". $date ."')");
                                        }
                                    }
                                }
                            }
                        }
                        $count++;
                    }
                    $MasterInventory = MasterInventory::insert($inventory);
                }
            }
        }
        echo "Inventory added sussceefully.";
        exit;
    }
}
